window.WB_BOOK=window.WB_BOOK||{};window.WB_BOOK["week14"]={"id":"week14","n":14,"section":"X","label":"Final Prep","title":"Final Paper 02 Prep: Data Analysis, Technique & Mixed Drill","titleText":"Final Paper 02 Prep: Data Analysis, Technique & Mixed Drill","subtitle":"Question 1 mastery, 20 model 'explain' answers, a 29-formula calculation bank and your exam-day plan","intro":"This is your **final Paper 02 book**. It is not a new topic: it pulls together everything from Sections A to E and trains the three things that win marks on Paper 02 — **(1) the data-analysis Question 1** (25 marks), **(2) clear 'explain' answers**, and **(3) accurate calculations**. Unit 4 gives you a time plan and a checklist for exam day. Work through it in the last two weeks before **Tuesday 5 January 2027**, then keep it for the Paper 01 revision before **Monday 25 January 2027**.","objectives":[{"code":"A","text":"Section A — Mechanics: scientific method & graphs, measurement, vectors, statics (moments, Hooke), dynamics (Newton, momentum), energy & power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics & kinetic theory: theories of heat, temperature & thermometers, phases, expansion, gas laws, specific heat & latent heat, heat transfer"},{"code":"C","text":"Section C — Waves & optics: wave motion, sound, EM spectrum, light (theories, reflection, refraction, TIR), lenses"},{"code":"D","text":"Section D — Electricity & magnetism: electrostatics, current, electrical quantities, circuits, mains, electronics, magnetism, electromagnetism & induction"},{"code":"E","text":"Section E — The physics of the atom: atomic models, atomic structure, radioactivity, half-life, nuclear energy"}],"formulaCard":[{"tex":"\\rho =m\\div V","meaning":"Density (A)","units":"kg m^−3^; ⟪1\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"},{"tex":"W=mg","meaning":"Weight; ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}\\ (A)⟫","units":"N"},{"tex":"\\text{moment }=F\\times d","meaning":"d = perpendicular distance to pivot (A)","units":"N m"},{"tex":"\\Sigma \\text{ clockwise moments }=\\Sigma \\text{ anticlockwise moments}","meaning":"Principle of moments, in equilibrium (A)","units":""},{"tex":"F=kx","meaning":"Hooke's law, up to the limit of proportionality (A)","units":"k in N m^−1^"},{"tex":"\\text{speed }=\\text{ distance }\\div \\text{ time};\\quad v=\\Delta s\\div \\Delta t","meaning":"Velocity = displacement ÷ time (A)","units":"m s^−1^"},{"tex":"a=(v-u)\\div t;\\quad v=u+\\text{ at}","meaning":"Acceleration (A)","units":"m s^−2^"},{"tex":"v\\text{–}t\\text{ graph: gradient }=a,\\ \\text{ area }=\\text{ distance}","meaning":"s–t graph: gradient = velocity (A)","units":""},{"tex":"F=ma","meaning":"Newton's 2nd law; F = resultant force (A)","units":"N"},{"tex":"p=mv;\\quad \\text{ momentum before }=\\text{ momentum after}","meaning":"Conservation of momentum (A)","units":"kg m s^−1^"},{"tex":"W=Fd","meaning":"Work done = energy transferred (A)","units":"J"},{"tex":"E_{p}=mgh;\\quad E_{k}=\\tfrac{1}{2}mv^{2}","meaning":"Potential and kinetic energy (A)","units":"J"},{"tex":"P=E\\div t","meaning":"Power (A, D)","units":"⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫"},{"tex":"\\text{efficiency }=\\text{ useful out }\\div \\text{ total in }\\times 100\\%","meaning":"Efficiency (A)","units":"%"},{"tex":"P=F\\div A;\\quad P=\\rho gh","meaning":"Pressure; pressure in a liquid (A)","units":"⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫"},{"text":"upthrust = weight of fluid displaced","meaning":"Archimedes' principle; floats when upthrust = weight (A)","units":"N"},{"tex":"T(K)=\\theta ({}^{\\circ}\\mathrm{C})+273","meaning":"Kelvin scale; absolute zero ⟪=-273\\,{}^{\\circ}\\mathrm{C}\\ (B)⟫","units":"K"},{"tex":"pV=\\text{ constant};\\quad V/T=\\text{ constant};\\quad p/T=\\text{ constant}","meaning":"Boyle's, Charles', pressure laws (T in K) (B)","units":""},{"tex":"p_{1}V_{1}/T_{1}=p_{2}V_{2}/T_{2}","meaning":"General gas law (B)","units":""},{"tex":"E_{H}=mc\\Delta \\theta ;\\quad C=mc","meaning":"Specific heat capacity c; heat capacity C (B)","units":"c in J kg^−1^ °C^−1^; water 4200"},{"tex":"E_{H}=ml","meaning":"Latent heat; ice ⟪l_{f}=3.4\\times 10^{5}⟫, water ⟪l_{v}=2.3\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\ (B)⟫","units":"J"},{"text":"heat lost = heat gained","meaning":"Method of mixtures (B)","units":"J"},{"tex":"v=f\\lambda ;\\quad T=1\\div f","meaning":"Wave equation; period (C)","units":"m s^−1^; Hz; s"},{"tex":"\\text{echo: }d=vt\\div 2","meaning":"Sound ≈ 330–340 m s^−1^ in air (C)","units":"m"},{"tex":"c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}","meaning":"Speed of ALL EM waves in vacuum (C)","units":""},{"text":"Radio, Microwave, Infrared, Visible, UV, X-ray, Gamma","meaning":"EM spectrum: wavelength DEcreases, frequency INcreases → (C)","units":""},{"tex":"\\text{angle }i=\\text{ angle }r","meaning":"Law of reflection (from the normal) (C)","units":"°"},{"tex":"n=\\sin i\\div \\sin r;\\quad n=c\\div v","meaning":"Refractive index — Snell's law (C)","units":"no unit"},{"tex":"\\sin c=1\\div n","meaning":"Critical angle; TIR when i > c, going dense → less dense (C)","units":"°"},{"tex":"1/f=1/u+1/v","meaning":"Lens formula (real positive; virtual image: v negative) (C)","units":"m or cm"},{"tex":"m=\\text{ image height }\\div \\text{ object height }=v\\div u","meaning":"Magnification (C)","units":"no unit"},{"tex":"Q=It;\\quad Q=ne","meaning":"Charge; ⟪e=1.6\\times 10^{-19}\\,\\mathrm{C}\\ (D)⟫","units":"C"},{"tex":"V=E\\div Q","meaning":"Potential difference = energy per coulomb (D)","units":"⟪V\\ (=\\mathrm{J}\\,\\mathrm{C}^{-1})⟫"},{"tex":"V=IR","meaning":"Ohm's law; ⟪R=V\\div I\\ (D)⟫","units":"Ω"},{"tex":"\\text{Series: }R=R_{1}+R_{2};\\quad \\text{ Parallel: }1/R=1/R_{1}+1/R_{2}","meaning":"Combining resistors (D)","units":"Ω"},{"tex":"P=IV=I^{2}R=V^{2}/R","meaning":"Electrical power (D)","units":"W"},{"tex":"E=Pt;\\quad 1\\,\\mathrm{kWh}=3.6\\times 10^{6}\\,\\mathrm{J}","meaning":"Electrical energy; cost ⟪=\\mathrm{kWh}⟫ × price (D)","units":"J or kWh"},{"tex":"\\text{fuse: }I=P\\div V,\\ \\text{ choose next rating above}","meaning":"Fuses 3 A, 5 A, 13 A (D)","units":"A"},{"tex":"V_{p}/V_{s}=N_{p}/N_{s};\\quad V_{p}I_{p}=V_{s}I_{s}","meaning":"Ideal transformer (D)","units":""},{"text":"Fleming's LEFT hand: thuMb = Motion, First = Field, seCond = Current","meaning":"Motor effect direction (D)","units":""},{"text":"Right-hand grip rule; Fleming's RIGHT hand (generator)","meaning":"Field round a wire/solenoid; induced current direction (D)","units":""},{"text":"AND, OR, NOT, NAND, NOR","meaning":"Logic gates: NAND = NOT-AND, NOR = NOT-OR (D)","units":""},{"tex":"A=Z+N","meaning":"Nucleon number = protons + neutrons (E)","units":""},{"tex":"\\alpha ={}^{4}_{2}\\text{He, }\\beta ={}^{0}_{-1}e,\\ \\gamma =EM\\text{ wave}","meaning":"Penetration: α stopped by paper, β by a few mm Al, γ reduced by thick lead (E)","units":""},{"tex":"\\text{amount left }=\\text{ original }\\div 2^{n}","meaning":"n = number of half-lives (E)","units":""},{"tex":"E=mc^{2}","meaning":"Mass defect → energy; ⟪c^{2}=9.0\\times 10^{16}\\ (E)⟫","units":"J"},{"tex":"\\text{gradient }=\\Delta y\\div \\Delta x","meaning":"Large triangle; unit y ÷ unit x (graph skills)","units":""}],"glossary":[{"term":"Anomalous result","def":"A reading that does not fit the pattern of the others; repeat it and ignore it when drawing the best-fit line."},{"term":"Best-fit line","def":"One straight ruled line (or smooth curve) passing as close as possible to all the points, with points evenly spread on both sides."},{"term":"Gradient","def":"Steepness of a line ⟪=\\Delta y\\div \\Delta x⟫, found with a large triangle; its unit is unit y ÷ unit x."},{"term":"Intercept","def":"The value where a line crosses an axis."},{"term":"Interpolation","def":"Reading a value from a graph between the plotted points."},{"term":"Extrapolation","def":"Extending a line beyond the plotted points to predict a value (e.g. absolute zero)."},{"term":"Directly proportional","def":"A straight-line graph through the origin: if x doubles, y doubles."},{"term":"Tangent","def":"A straight line touching a curve at one point; its gradient is the gradient of the curve at that point."},{"term":"Significant figures","def":"The meaningful digits in a number; final answers usually to 2 or 3 s.f."},{"term":"Random error","def":"Unpredictable scatter of readings about the true value; reduced by repeating and averaging."},{"term":"Systematic error","def":"An error that shifts every reading by the same amount in the same direction, e.g. a zero error."},{"term":"Parallax error","def":"Error from reading a scale at an angle; avoid by placing the eye perpendicular to the scale."},{"term":"Independent variable","def":"The quantity you change on purpose in an experiment."},{"term":"Dependent variable","def":"The quantity you measure, which changes as a result."},{"term":"Controlled variable","def":"A quantity kept the same so the test is fair."},{"term":"Hypothesis","def":"A testable statement predicting how one variable affects another."},{"term":"Precaution","def":"A step taken to make readings more accurate or the experiment safer."},{"term":"Error carried forward (ECF)","def":"Examiners give marks in a later part for correct working that uses your own (wrong) earlier answer."}],"studyPlan":[["Day after session","Unit 1 notes + Data sets 1–3 (1.4–1.10)","1 h",""],["Day 2","Unit 2: read E1–E20 aloud, cover and test; Unit 2 practice","45 min",""],["Day 3","Units 3A–3C: cover each worked example, try it, then its two practice questions","1 h",""],["Day 4","S1–S4 TIMED (20 min each) or PP1/PP2 (40 min each); mark; Mistake Log","45 min",""],["Every day","Master formula card + 3 model answers from memory","10 min",""]],"lessons":[{"id":"week14.1","kind":"unit","unit":"1","title":"Data Analysis — Mastering Question 1","titleText":"Data Analysis — Mastering Question 1","goals":[{"code":"A","text":"Section A — Mechanics: scientific method & graphs, measurement, vectors, statics (moments, Hooke), dynamics (Newton, momentum), energy & power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics & kinetic theory: theories of heat, temperature & thermometers, phases, expansion, gas laws, specific heat & latent heat, heat transfer"},{"code":"C","text":"Section C — Waves & optics: wave motion, sound, EM spectrum, light (theories, reflection, refraction, TIR), lenses"},{"code":"D","text":"Section D — Electricity & magnetism: electrostatics, current, electrical quantities, circuits, mains, electronics, magnetism, electromagnetism & induction"},{"code":"E","text":"Section E — The physics of the atom: atomic models, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["A","B","C","D","E"],"words":[{"term":"Best-fit line","def":"One straight ruled line (or smooth curve) passing as close as possible to all the points, with points evenly spread on both sides."},{"term":"Gradient","def":"Steepness of a line ⟪=\\Delta y\\div \\Delta x⟫, found with a large triangle; its unit is unit y ÷ unit x."},{"term":"Intercept","def":"The value where a line crosses an axis."},{"term":"Interpolation","def":"Reading a value from a graph between the plotted points."},{"term":"Extrapolation","def":"Extending a line beyond the plotted points to predict a value (e.g. absolute zero)."},{"term":"Directly proportional","def":"A straight-line graph through the origin: if x doubles, y doubles."},{"term":"Tangent","def":"A straight line touching a curve at one point; its gradient is the gradient of the curve at that point."},{"term":"Significant figures","def":"The meaningful digits in a number; final answers usually to 2 or 3 s.f."},{"term":"Random error","def":"Unpredictable scatter of readings about the true value; reduced by repeating and averaging."},{"term":"Systematic error","def":"An error that shifts every reading by the same amount in the same direction, e.g. a zero error."},{"term":"Parallax error","def":"Error from reading a scale at an angle; avoid by placing the eye perpendicular to the scale."},{"term":"Hypothesis","def":"A testable statement predicting how one variable affects another."},{"term":"Precaution","def":"A step taken to make readings more accurate or the experiment safer."}],"learn":{"notes":[{"type":"p","text":"**Question 1 of Paper 02 is worth 25 marks — a quarter of the whole paper.** It is always a practical/data question: a table of results, a graph to plot, a gradient to find, a value to read off, and a few questions about the experiment (precautions, errors, variables, planning). The topic can come from ANY section, A to E. The good news: the *skills* are the same every year, so they can be practised until they are automatic."},{"type":"table","headers":["Part of Q1","Typical marks","What earns the marks"],"rows":[["Complete the table","2–4","Correct calculation, SAME number of decimal places as the column"],["Plot the graph","6–8","**SPLAT**: Scale, Points, Labels, Line, Title"],["Gradient","3–4","Large triangle drawn on the graph, values read correctly, answer with UNIT"],["Read off / intercept","2–3","Dashed construction lines shown, value with unit"],["Relationship / conclusion","2","'Straight line through the origin, so y is directly proportional to x'"],["Experiment questions","4–8","Variables, precautions, sources of error, planning steps"]]},{"type":"h","text":"1. The SPLAT checklist for every graph"},{"type":"img","src":"img/week14/splat_example","alt":"Figure 1.1 — A full-mark graph: every SPLAT point visible","caption":"Figure 1.1 — A full-mark graph: every SPLAT point visible","width":5.4,"w":1214,"h":854},{"type":"table","headers":["Letter","Check","How examiners mark it"],"rows":[["**S** — Scale","Use 1, 2, 5 or 10 units per big square (or 0.1, 0.2, 0.5…). NEVER 3, 6, 7 or 9. Plotted points must cover MORE THAN HALF the grid in both directions.","1–2 marks. Lost for awkward scales or a tiny graph in one corner."],["**P** — Points","Plot every point with a small sharp cross (×) or a dot in a circle (⊙). Check each one twice.","2 marks; −1 for each wrong point."],["**L** — Labels","Both axes: *quantity / unit*, e.g. 'Current, I / A'. The FIRST variable named in 'plot y against x' goes UP (y-axis).","1–2 marks."],["**L** — Line","ONE thin, ruled best-fit line (or a smooth curve). Roughly equal numbers of points on each side. Do NOT join dot-to-dot. Ignore an anomalous point.","1–2 marks."],["**T** — Title","'Graph of y against x', e.g. 'Graph of p.d. against current'.","Often 1 mark."]]},{"type":"warn","text":"Plotting 'y against x' the wrong way round. **'Plot V against I'** means V on the vertical (y) axis and I on the horizontal (x) axis. Read the question twice."},{"type":"h","text":"2. Gradient of a straight line"},{"type":"formula","tex":"\\text{gradient }=\\Delta y\\div \\Delta x=(y_{2}-y_{1})\\div (x_{2}-x_{1})","where":["⟪\\Delta y⟫ = change in the y-value (vertical side of the triangle)","⟪\\Delta x⟫ = change in the x-value (horizontal side)","Unit of gradient = unit of y ÷ unit of x"],"label":"GRADIENT"},{"type":"steps","items":["Draw a LARGE triangle on the line — its sides should cover at least half of the line.","Use points ON THE LINE, not data points (unless a data point sits exactly on the line).","Read the coordinates of both corners carefully, using the scale.","Write ⟪\\Delta y\\div \\Delta x⟫ with the numbers, then calculate.","Give the UNIT (unit y ÷ unit x) and round to 2 or 3 significant figures."]},{"type":"table","headers":["Graph","The gradient gives…","Section"],"rows":[["Extension (y) against load (x)","1 ÷ spring constant (⟪k=1⟫/gradient)","A"],["Displacement against time","velocity","A"],["Velocity against time","acceleration (area under = distance)","A"],["T^2^ against length (pendulum)","4π^2^/g","A"],["Mass against volume","density","A"],["v^2^ against h (falling / sliding object)","2g (because ⟪\\tfrac{1}{2}mv^{2}=mgh⟫)","A"],["Energy supplied against Δθ (heating)","mc, the heat capacity","B"],["sin i against sin r","refractive index n","C"],["V against I","resistance R","D"],["V~s~ against N~s~ (transformer)","⟪V_{p}\\div N_{p}⟫","D"]]},{"type":"h","text":"3. Curves: the tangent"},{"type":"p","text":"When the graph is a curve, the gradient is different at every point. To find the gradient at one point, draw a **tangent**: a straight ruled line that just touches the curve at that point, then find the gradient of the tangent with a large triangle."},{"type":"img","src":"img/week14/tangent","alt":"Figure 1.2 — Tangent at t = 3.0 s: gradient = 9.0 ÷ 3.0 = 3.0 m s−1 = velocity at that instant","caption":"Figure 1.2 — Tangent at ⟪t=3.0\\,\\mathrm{s}⟫: gradient ⟪=9.0\\div 3.0=3.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ = velocity at that instant","width":4.4,"w":1094,"h":734},{"type":"h","text":"4. Intercepts, interpolation and extrapolation"},{"type":"img","src":"img/week14/interp_extrap","alt":"Figure 1.3 — Interpolation (read INSIDE the data) and extrapolation (extend the line beyond the data)","caption":"Figure 1.3 — Interpolation (read INSIDE the data) and extrapolation (extend the line beyond the data)","width":4.8,"w":1174,"h":774},{"type":"table","headers":["Word","Meaning","How to show it"],"rows":[["Intercept","Where the line crosses an axis","Read the value where the line cuts the axis; give the unit"],["Interpolation","Reading a value BETWEEN the plotted points","Draw dashed lines from the axis to the line and across to the other axis"],["Extrapolation","Extending the line BEYOND the plotted points","Continue the ruled line as a dashed line to the axis (e.g. to find absolute zero)"]]},{"type":"remember","text":"A **straight line through the origin** means **directly proportional** (double x → double y). A straight line that does NOT pass through the origin is a **linear** relationship, but NOT proportional."},{"type":"h","text":"5. Tables of results"},{"type":"bullets","items":["Column headings carry **quantity / unit**, e.g. 'Time for 20 oscillations, t / s'. Units go in the heading, NOT after every number.","Every value in a column has the **same number of decimal places** (this shows the precision of the instrument: a metre rule reads to 0.1 cm, a stopwatch to 0.01 s).","Record repeat readings and the average.","Calculated values (e.g. sin i, 1/d, T^2^) are given to the same number of significant figures as the data, or one more."]},{"type":"h","text":"6. Significant figures (s.f.)"},{"type":"table","headers":["Rule","Example","Number of s.f."],"rows":[["All non-zero digits count","4.52","3"],["Zeros BETWEEN digits count","305","3"],["Leading zeros never count","0.0072","2"],["Trailing zeros after a decimal point count","2.50","3"],["Standard form: count the digits in front","⟪3.0\\times 10^{8}⟫","2"]]},{"type":"tip","text":"Give a final answer to the **same number of s.f. as the least precise data** in the question — usually 2 or 3 s.f. Never copy 8 digits from the calculator. Keep full figures in the middle of a calculation and round only at the end."},{"type":"h","text":"7. Errors and precautions"},{"type":"img","src":"img/week14/parallax","alt":"Figure 1.4 — Avoiding parallax: eye level with the bottom of the meniscus (or the pointer)","caption":"Figure 1.4 — Avoiding parallax: eye level with the bottom of the meniscus (or the pointer)","width":4.2,"w":1092,"h":614},{"type":"table","headers":["Type of error","Meaning","Examples","How to reduce it"],"rows":[["Random error","Readings scatter unpredictably above and below the true value","Reaction time on a stopwatch; small changes in conditions; radioactive count rate","Repeat readings and take the average; time many oscillations"],["Systematic error","Every reading is wrong by the same amount, in the same direction","Zero error on a meter, micrometer or newton-meter; a stretched tape; parallax always from the same side","Check and correct the zero; calibrate the instrument; read at eye level"],["Parallax error","Reading a scale from an angle","Measuring cylinder, metre rule, meter needle","Eye perpendicular to the scale (in line with the reading)"]]},{"type":"table","headers":["Experiment","Precautions that score marks"],"rows":[["Pendulum (A)","Small amplitude (<10°); time 20 oscillations; start timing at the centre of the swing; repeat and average"],["Hooke's law (A)","Do not exceed the elastic limit; read pointer at eye level; check spring returns to original length"],["Heating / specific heat (B)","Insulate (lag) the container; stir before reading the temperature; read thermometer at eye level"],["Refraction / lenses (C)","Use thin pencil lines and narrow rays; place pins far apart; darken the room for lens images"],["Electrical (D)","Switch off between readings so the wire does not heat up; check meter zero; connect ammeter in series, voltmeter in parallel"],["Radioactivity (E)","Measure and subtract background count; handle sources with tongs, point away from the body; repeat counts"]]},{"type":"h","text":"8. Planning and designing an experiment"},{"type":"p","text":"Paper 02 (and the SBA) can ask you to **plan and design** an experiment to test a hypothesis. Use this template every time — each heading usually earns at least one mark:"},{"type":"table","headers":["Heading","What to write"],"rows":[["Hypothesis","A testable statement: 'As the length of the wire increases, its resistance increases.'"],["Aim","'To investigate how ___ affects ___.'"],["Variables","Independent (what YOU change); dependent (what you MEASURE); controlled (what you keep the SAME — name at least two)"],["Apparatus","List with sizes/ranges (e.g. 0–1 A ammeter, 1 m nichrome wire, metre rule)"],["Diagram","Labelled, ruled, correct circuit symbols"],["Method","Numbered steps, in the order you would do them, including at least 5 different values and repeats"],["Results","A table with headings and units, ready for the readings"],["Treatment of results","What graph you will plot and what it should show"],["Expected results / conclusion","What result would support the hypothesis"],["Precautions / limitations","At least two precautions; one source of error"]]},{"type":"tip","text":"Planning questions are marked on whether another student could **follow your method and get results**. Be specific: 'measure the length with a metre rule' not 'measure the length'."}],"examples":[{"id":"week14.1.e1","title":"Gradient with a unit — and what it means","question":"Use Figure 1.1. Find the gradient of the graph of extension against load and hence the spring constant k.","steps":[{"label":"Triangle","text":"Corners on the line at (1.0 N, 2.0 mm) and (6.0 N, 11.9 mm)."},{"label":"Formula","text":"gradient ⟪=\\Delta y\\div \\Delta x⟫"},{"label":"Substitute","text":"gradient ⟪=(11.9-2.0)\\div (6.0-1.0)=9.9\\div 5.0⟫"},{"label":"Calculate","text":"gradient ⟪=1.98\\,\\mathrm{mm}\\,\\mathrm{N}^{-1}\\approx 2.0\\,\\mathrm{mm}\\,\\mathrm{N}^{-1}⟫"},{"label":"Meaning","text":"⟪F=kx⟫, so ⟪x=F/k⟫ and gradient ⟪=1/k⟫. ⟪k=1\\div 1.98=0.505\\,\\mathrm{N}\\,\\mathrm{mm}^{-1}=505\\,\\mathrm{N}\\,\\mathrm{m}^{-1}⟫"}],"answer":"Gradient = 2.0 mm N^−1^ (3 s.f.: 1.98); spring constant ⟪k\\approx 0.51\\,\\mathrm{N}\\,\\mathrm{mm}^{-1}\\ (\\approx 510\\,\\mathrm{N}\\,\\mathrm{m}^{-1})⟫."},{"id":"week14.1.e2","title":"Significant figures and a period","question":"Three timings of 10 oscillations were 15.2 s, 15.6 s and 15.4 s. Find the period T to a sensible number of s.f.","steps":[{"label":"Average","text":"⟪(15.2+15.6+15.4)\\div 3=46.2\\div 3=15.4\\,\\mathrm{s}⟫"},{"label":"Formula","text":"T = time ÷ number of oscillations"},{"label":"Substitute","text":"⟪T=15.4\\div 10⟫"},{"label":"Calculate","text":"T = 1.54 s (3 s.f., matching the data)"}],"answer":"⟪T=1.54\\,\\mathrm{s}⟫"},{"id":"week14.1.e3","title":"Gradient of a tangent","question":"Use Figure 1.2. Find the velocity of the object at ⟪t=3.0\\,\\mathrm{s}⟫.","steps":[{"label":"Method","text":"The tangent at ⟪t=3.0\\,\\mathrm{s}⟫ runs from (1.5 s, 0 m) to (4.5 s, 9.0 m)."},{"label":"Formula","text":"velocity = gradient ⟪=\\Delta s\\div \\Delta t⟫"},{"label":"Substitute","text":"⟪v=(9.0-0)\\div (4.5-1.5)=9.0\\div 3.0⟫"},{"label":"Calculate","text":"⟪v=3.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"3.0 m s^−1^"},{"id":"week14.1.e4","title":"A planning question (Section B)","question":"Plan an experiment to test the hypothesis: 'A dull black can cools faster than a shiny silver can.'","steps":[{"label":"Aim","text":"To investigate how the colour/surface of a can affects its rate of cooling."},{"label":"Variables","text":"Independent: surface (dull black or shiny silver). Dependent: temperature after each minute. Controlled: same size cans, same volume (200 cm^3^) and starting temperature (80 °C) of water, same room, lids on both."},{"label":"Apparatus","text":"Two identical cans (one painted dull black, one shiny), two thermometers (0–110 °C), measuring cylinder, kettle, stopwatch, lids."},{"label":"Method","text":"1. Pour 200 cm^3^ of hot water into each can. 2. Insert a thermometer through each lid. 3. When both read 80 °C, start the stopwatch. 4. Record both temperatures every minute for 15 minutes. 5. Repeat the experiment and average."},{"label":"Results","text":"Table: Time / min | Temperature of black can / °C | Temperature of silver can / °C. Plot both cooling curves on the same axes."},{"label":"Expected result","text":"If the black can's temperature falls faster (steeper curve), the hypothesis is supported: dull black surfaces are better emitters of radiation."},{"label":"Precautions","text":"Stir gently before each reading; read thermometers at eye level; keep cans away from draughts and from each other."}],"answer":"A full plan covers hypothesis, aim, variables, apparatus, method, results table, expected result and precautions."}]},"tryit":[{"id":"week14.1.p1","kind":"self","q":"State the number of significant figures in (i) 0.0450 (ii) ⟪3.20\\times 10^{3}⟫ (iii) 400.5. (iv) Round 2.3468 to 3 s.f.","marks":4,"level":3,"lines":2,"scheme":"(i) 3 (1)  (ii) 3 (1)  (iii) 4 (1)  (iv) 2.35 (1).","points":[{"text":"(i) 3","marks":1},{"text":"(ii) 3","marks":1},{"text":"(iii) 4","marks":1},{"text":"(iv) 2.35","marks":1}],"section":"try","hint":{"text":"Look back at Example 2 (Significant figures and a period). Start like this: Average: ⟪(15.2+15.6+15.4)\\div 3=46.2\\div 3=15.4\\,\\mathrm{s}⟫","from":2}},{"id":"week14.1.p2","kind":"self","q":"A student's table has the headings **Length (cm) | Time | Period** and the length values 20, 30.0, 40.25, 50. State THREE faults and correct them.","marks":3,"level":2,"lines":4,"scheme":"Any three (1 each): units should be written as quantity / unit, e.g. 'Length, l / cm'; 'Time' has no unit — should be 'Time for 20 oscillations, t / s'; 'Period' has no unit — 'Period, T / s'; values not to the same number of decimal places — should be 20.0, 30.0, 40.3 (or 40.2), 50.0 (all to 0.1 cm).","points":[{"text":"Any three (1 each): units should be written as quantity / unit, e.g. 'Length, l / cm'; 'Time' has no unit — should be 'Time for 20 oscillations, t / s'; 'Period' has no unit — 'Period, T / s'; values not to the same number of decimal places — should be 20.0, 30.0, 40.3 (or 40.2), 50.0 (all to 0.1 cm).","marks":3,"each":true}],"section":"try"}],"practice":[{"id":"week14.1.p3","kind":"self","q":"The x-values in a table go from 0 to 4.6 N and the y-values from 0 to 37 cm. The grid is 16 big squares wide and 12 big squares tall. Choose a suitable scale for each axis and show that your graph covers more than half the grid.","marks":2,"level":2,"lines":3,"scheme":"x: 0.5 N per big square → 4.6 N uses 9.2 of 16 squares (> 8, more than half) (1); y: 5 cm per big square → 37 cm uses 7.4 of 12 squares (> 6) (1). (Do not accept scales of 3, 6, 7 or 9 units per square.)","points":[{"text":"x: 0.5 N per big square → 4.6 N uses 9.2 of 16 squares (> 8, more than half)","marks":1},{"text":"y: 5 cm per big square → 37 cm uses 7.4 of 12 squares (> 6) (Do not accept scales of 3, 6, 7 or 9 units per square.)","marks":1}],"section":"practice"},{"id":"week14.1.p4","kind":"self","q":"**Data set 1 (Section C — refraction).** A student shone rays into a glass block and measured the angle of refraction r for different angles of incidence i. Copy and complete the table, giving sin values to 3 decimal places.","marks":4,"level":3,"blocks":[{"type":"table","headers":["Angle of incidence, i / °","20","30","40","50","60","70"],"rows":[["Angle of refraction, r / °","13","20","25","31","35","39"],["sin i","0.342","0.500","","0.766","0.866",""],["sin r","0.225","","0.423","0.515","","0.629"]]}],"lines":3,"scheme":"⟪\\sin 40^{\\circ}=0.643⟫ (1); ⟪\\sin 70^{\\circ}=0.940⟫ (1); sin 20° (for r) = 0.342 (1); ⟪\\sin 35^{\\circ}=0.574⟫ (1).","points":[{"text":"⟪\\sin 40^{\\circ}=0.643⟫","marks":1},{"text":"⟪\\sin 70^{\\circ}=0.940⟫","marks":1},{"text":"sin 20° (for r) = 0.342","marks":1},{"text":"⟪\\sin 35^{\\circ}=0.574⟫","marks":1}],"section":"practice"},{"id":"week14.1.p5","kind":"self","q":"Plot a graph of sin i (y-axis) against sin r (x-axis) for Data set 1 on the grid. Draw the line of best fit.","marks":7,"level":3,"blocks":[{"type":"img","src":"img/week14/grid","alt":"Graph grid","caption":"Graph grid","width":5.6,"w":1254,"h":974}],"lines":1,"scheme":"Axes labelled 'sin i' and 'sin r' (no unit — they are ratios) (1); sensible scale, e.g. 0.05 per big square on x (uses 12.6 squares) and 0.1 per big square on y (uses 9.4 squares) (2); all six points correct (2, −1 per error); straight ruled best-fit line through (or very close to) the origin (1); title 'Graph of sin i against sin r' (1).","points":[{"text":"Axes labelled 'sin i' and 'sin r' (no unit — they are ratios)","marks":1},{"text":"sensible scale, e.g. 0.05 per big square on x (uses 12.6 squares) and 0.1 per big square on y (uses 9.4 squares)","marks":2},{"text":"all six points correct (2, −1 per error); straight ruled best-fit line through (or very close to) the origin","marks":1},{"text":"title 'Graph of sin i against sin r'","marks":1}],"conf":"low","section":"practice"},{"id":"week14.1.p6","kind":"self","q":"(a) Find the gradient of your Data set 1 graph. (b) What does the gradient represent? (c) Use your answer to calculate the critical angle of the glass.","marks":5,"level":3,"lines":5,"scheme":"(a) Large triangle shown (1); gradient ≈ ⟪0.940\\div 0.629\\approx 1.50⟫ (accept 1.45–1.55) (1). (b) The refractive index n of the glass, because ⟪n=\\sin i\\div \\sin r⟫ (1). (c) ⟪\\sin c=1/n=1\\div 1.50=0.667⟫ (1); ⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫ (accept 40°–44° from their n) (1).","points":[{"text":"(a) Large triangle shown","marks":1},{"text":"gradient ≈ ⟪0.940\\div 0.629\\approx 1.50⟫ (accept 1.45–1.55)","marks":1},{"text":"(b) The refractive index n of the glass, because ⟪n=\\sin i\\div \\sin r⟫","marks":1},{"text":"(c) ⟪\\sin c=1/n=1\\div 1.50=0.667⟫","marks":1},{"text":"⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫ (accept 40°–44° from their n)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Gradient of a tangent). Start like this: Method: The tangent at ⟪t=3.0\\,\\mathrm{s}⟫ runs from (1.5 s, 0 m) to (4.5 s, 9.0 m).","from":3}},{"id":"week14.1.p7","kind":"self","q":"**Data set 2 (Section D — resistance).** The current through a resistor was measured for different p.d.s. Plot a graph of V (y-axis) against I (x-axis), draw the line of best fit and circle any anomalous point.","marks":8,"level":3,"blocks":[{"type":"table","headers":["p.d., V / V","0.0","0.5","1.0","1.5","2.0","2.5","3.0"],"rows":[["Current, I / A","0.00","0.11","0.20","0.31","0.46","0.50","0.61"]]},{"type":"img","src":"img/week14/grid","alt":"Graph grid","caption":"Graph grid","width":5.6,"w":1254,"h":974}],"lines":2,"scheme":"Axes 'p.d., V / V' and 'Current, I / A' (1); sensible scale using more than half the grid, e.g. x: 0.05 A per big square (12.2 squares), y: 0.25 V per big square (4 big squares ⟪=1\\,\\mathrm{V}⟫; 12 squares) (2); all seven points correct (2); straight ruled line through the origin (1); line IGNORES the point (0.46 A, 2.0 V) (1); that point circled/identified as anomalous (1).","points":[{"text":"Axes 'p.d., V / V' and 'Current, I / A'","marks":1},{"text":"sensible scale using more than half the grid, e.g. x: 0.05 A per big square (12.2 squares), y: 0.25 V per big square (4 big squares ⟪=1\\,\\mathrm{V}⟫; 12 squares)","marks":2},{"text":"all seven points correct","marks":2},{"text":"straight ruled line through the origin","marks":1},{"text":"line IGNORES the point (0.46 A, 2.0 V)","marks":1},{"text":"that point circled/identified as anomalous","marks":1}],"section":"practice"},{"id":"week14.1.p8","kind":"self","q":"For Data set 2: (a) use the gradient to find the resistance. (b) Is the resistor ohmic? Explain. (c) What should the student do about the anomalous reading? (d) Describe how the graph would differ for a filament lamp.","marks":5,"level":3,"lines":6,"scheme":"(a) gradient ⟪=\\Delta V\\div \\Delta I⟫, e.g. ⟪3.0\\div 0.605\\approx 5.0\\,\\Omega⟫ (accept 4.8–5.2 Ω) (1). (b) Yes — straight line through the origin, so ⟪V\\propto I⟫, constant resistance (1). (c) Repeat the reading at 2.0 V (expected ⟪I\\approx 0.40\\,\\mathrm{A}⟫) and ignore 0.46 A when drawing the line (1). (d) The graph curves (1): V rises more steeply at higher currents because the filament gets hotter and its resistance increases (1).","points":[{"text":"(a) gradient ⟪=\\Delta V\\div \\Delta I⟫, e.g. ⟪3.0\\div 0.605\\approx 5.0\\,\\Omega⟫ (accept 4.8–5.2 Ω)","marks":1},{"text":"(b) Yes — straight line through the origin, so ⟪V\\propto I⟫, constant resistance","marks":1},{"text":"(c) Repeat the reading at 2.0 V (expected ⟪I\\approx 0.40\\,\\mathrm{A}⟫) and ignore 0.46 A when drawing the line","marks":1},{"text":"(d) The graph curves","marks":1},{"text":": V rises more steeply at higher currents because the filament gets hotter and its resistance increases","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Gradient of a tangent). Start like this: Method: The tangent at ⟪t=3.0\\,\\mathrm{s}⟫ runs from (1.5 s, 0 m) to (4.5 s, 9.0 m).","from":3}},{"id":"week14.1.p9","kind":"self","q":"**Data set 3 (Section B — pressure law).** A fixed mass of gas at constant volume was heated. Plot p (y-axis) against θ (x-axis). Your θ-axis must run from −300 °C to 100 °C and your p-axis from 0 kPa. Extend (extrapolate) the line as a dashed line until it meets the θ-axis.","marks":7,"level":3,"blocks":[{"type":"table","headers":["Temperature, θ / °C","0","20","40","60","80","100"],"rows":[["Pressure, p / kPa","101","108","116","123","131","138"]]},{"type":"img","src":"img/week14/grid","alt":"Graph grid","caption":"Graph grid","width":5.6,"w":1254,"h":974}],"lines":1,"scheme":"Axes labelled with units (1); sensible scale that fits the full −300 °C to 100 °C range and 0–140 kPa, e.g. x: 25 °C per big square (4 squares ⟪=100\\,{}^{\\circ}\\mathrm{C}⟫; 16 squares), y: 20 kPa per big square (7 squares used) (1); six points correct (2); ruled best-fit line (1); line extrapolated (dashed) to ⟪p=0⟫ (1); title (1).","points":[{"text":"Axes labelled with units","marks":1},{"text":"sensible scale that fits the full −300 °C to 100 °C range and 0–140 kPa, e.g. x: 25 °C per big square (4 squares ⟪=100\\,{}^{\\circ}\\mathrm{C}⟫; 16 squares), y: 20 kPa per big square (7 squares used)","marks":1},{"text":"six points correct","marks":2},{"text":"ruled best-fit line","marks":1},{"text":"line extrapolated (dashed) to ⟪p=0⟫","marks":1},{"text":"title","marks":1}],"section":"practice"},{"id":"week14.1.p10","kind":"self","q":"For Data set 3: (a) Use your graph to find the pressure at 50 °C (show construction lines). (b) State the temperature where your line meets the θ-axis and name this temperature. (c) Explain, using kinetic theory, why the pressure rises when the gas is heated.","marks":5,"level":3,"lines":6,"scheme":"(a) Dashed lines shown (1); ⟪p\\approx 119⟫–120 kPa (1). (b) About −270 °C (accept −260 to −285 °C; theory −273 °C), absolute zero / 0 K (1). (c) Molecules gain kinetic energy and move faster (1); they hit the walls more often and harder, so a greater force per unit area / pressure (1).","points":[{"text":"(a) Dashed lines shown","marks":1},{"text":"⟪p\\approx 119⟫–120 kPa","marks":1},{"text":"(b) About −270 °C (accept −260 to −285 °C; theory −273 °C), absolute zero / 0 K","marks":1},{"text":"(c) Molecules gain kinetic energy and move faster","marks":1},{"text":"they hit the walls more often and harder, so a greater force per unit area / pressure","marks":1}],"section":"practice"}],"exit":[{"id":"week14.1.p11","kind":"self","q":"**Planning.** Plan and design an experiment to test the hypothesis: 'The resistance of a nichrome wire increases as its length increases.' Include: aim, variables, apparatus (with a circuit diagram), method, results table and ONE precaution.","marks":8,"level":3,"lines":14,"scheme":"Aim: to investigate how length affects resistance of a wire (1). Variables: independent = length; dependent = resistance (from V and I); controlled = same wire material/thickness (diameter), same temperature (1). Apparatus: nichrome wire on a metre rule, cell, switch, ammeter, voltmeter, crocodile clips, connecting wires (1). Diagram: ammeter in series, voltmeter in parallel across the length of wire being tested (1). Method: connect clips 20.0 cm apart, close switch, read V and I, open switch (1); repeat for 40, 60, 80, 100 cm (at least 5 lengths), repeat each reading (1). Results: table Length, l / cm | V / V | I / A | ⟪R=V/I/\\Omega⟫; plot R against l — straight line supports hypothesis (1). Precaution: switch off between readings so the wire does not heat up / read meters at eye level / check zero errors (1).","points":[{"text":"Aim: to investigate how length affects resistance of a wire","marks":1},{"text":"Variables: independent = length; dependent = resistance (from V and I); controlled = same wire material/thickness (diameter), same temperature","marks":1},{"text":"Apparatus: nichrome wire on a metre rule, cell, switch, ammeter, voltmeter, crocodile clips, connecting wires","marks":1},{"text":"Diagram: ammeter in series, voltmeter in parallel across the length of wire being tested","marks":1},{"text":"Method: connect clips 20.0 cm apart, close switch, read V and I, open switch","marks":1},{"text":"repeat for 40, 60, 80, 100 cm (at least 5 lengths), repeat each reading","marks":1},{"text":"Results: table Length, l / cm | V / V | I / A | ⟪R=V/I/\\Omega⟫; plot R against l — straight line supports hypothesis","marks":1},{"text":"Precaution: switch off between readings so the wire does not heat up / read meters at eye level / check zero errors","marks":1}],"section":"exit"},{"id":"week14.1.p12","kind":"self","q":"Give ONE source of error and ONE matching precaution for each experiment: (a) timing a pendulum (b) reading a measuring cylinder (c) measuring a radioactive count rate (d) finding the specific heat capacity of a metal block.","marks":4,"level":3,"lines":5,"scheme":"(a) Reaction time → time 20 oscillations / repeat and average (1). (b) Parallax → eye level with bottom of meniscus (1). (c) Random decay/background radiation → repeat counts, subtract background (1). (d) Heat lost to surroundings → insulate (lag) the block / use oil in the thermometer hole (1).","points":[{"text":"(a) Reaction time → time 20 oscillations / repeat and average","marks":1},{"text":"(b) Parallax → eye level with bottom of meniscus","marks":1},{"text":"(c) Random decay/background radiation → repeat counts, subtract background","marks":1},{"text":"(d) Heat lost to surroundings → insulate (lag) the block / use oil in the thermometer hole","marks":1}],"section":"exit"}],"warmup":[{"id":"week14.1.w1","kind":"self","q":"What did Rutherford conclude from the few α particles that bounced back off the gold foil?","marks":1,"level":1,"scheme":"The atom has a tiny, dense, positively charged nucleus.","points":[{"text":"The atom has a tiny, dense, positively charged nucleus.","marks":1}],"section":"warmup","src":"week12.r1"},{"id":"week14.1.w2","kind":"self","q":"How many neutrons are in ^40^~20~Ca?","marks":1,"level":1,"scheme":"⟪40-20=20⟫ neutrons.","points":[{"text":"⟪40-20=20⟫ neutrons.","marks":1}],"section":"warmup","src":"week12.r2"},{"id":"week14.1.w3","kind":"self","q":"Which radiation is stopped by paper, and what is it?","marks":1,"level":1,"scheme":"Alpha (α), a helium nucleus (2 protons + 2 neutrons).","points":[{"text":"Alpha (α), a helium nucleus (2 protons + 2 neutrons).","marks":1}],"section":"warmup","src":"week12.r3"},{"id":"week14.1.w4","kind":"self","q":"Complete: ^14^~6~C → ? + ^0^~−1~e","marks":1,"level":1,"scheme":"^14^~7~N","points":[{"text":"^14^~7~N","marks":1}],"section":"warmup","src":"week12.r4"},{"id":"week14.1.w5","kind":"self","q":"A source has a half-life of 4 hours. What fraction is left after 12 hours?","marks":1,"level":1,"scheme":"3 half-lives, so 1/8.","points":[{"text":"3 half-lives, so 1/8.","marks":1}],"section":"warmup","src":"week12.r5"}],"quickStart":[{"type":"p","text":"Before you start, remember how Paper 02 marks are earned:"},{"type":"bullets","items":["**1 mark ≈ 1 point.** A 4-mark 'explain' needs 4 separate physics points.","**Calculations:** formula (1) + substitution (1) + answer with unit (1) is the usual pattern.","**Graphs:** SPLAT — Scale, Points, Labels, Line, Title.","**Units and s.f.** are checked — 2 or 3 significant figures, and a unit on every answer."]},{"type":"fill","text":"Write the four letters of SPLAT and what each stands for:","lines":2},{"type":"fill","text":"Write the three steps for every calculation:","lines":1}],"n":101},{"id":"week14.2","kind":"unit","unit":"2","title":"The 'Explain' Toolkit — 20 Model Answers","titleText":"The 'Explain' Toolkit — 20 Model Answers","goals":[{"code":"A","text":"Section A — Mechanics: scientific method & graphs, measurement, vectors, statics (moments, Hooke), dynamics (Newton, momentum), energy & power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics & kinetic theory: theories of heat, temperature & thermometers, phases, expansion, gas laws, specific heat & latent heat, heat transfer"},{"code":"C","text":"Section C — Waves & optics: wave motion, sound, EM spectrum, light (theories, reflection, refraction, TIR), lenses"},{"code":"D","text":"Section D — Electricity & magnetism: electrostatics, current, electrical quantities, circuits, mains, electronics, magnetism, electromagnetism & induction"},{"code":"E","text":"Section E — The physics of the atom: atomic models, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["A","B","C","D","E"],"words":[],"learn":{"notes":[{"type":"p","text":"About **half of the marks in Paper 02** are for words, not numbers: *state, define, explain, describe, distinguish, suggest*. Students lose these marks because their answers are too short or too vague. Examiners give **one mark per correct physics point**. So: count the marks, then write that many separate points."},{"type":"h","text":"1. Command words — what the examiner wants"},{"type":"table","headers":["Command word","What to do","Length"],"rows":[["State / Name / List","A short fact, no reason needed","A word or one line"],["Define","The exact textbook definition (with the unit if asked)","One sentence"],["Describe","Say what happens / the steps, in order","One point per mark"],["Explain","Give the REASON using physics ideas — say WHY","Point + reason for each mark"],["Distinguish between","Give the difference for BOTH things","Both sides each time"],["Suggest","Apply your physics to a new situation; there may be more than one right answer","Short, reasoned"],["Calculate / Determine","Numbers — show formula, substitution, answer with unit","Working shown"],["Sketch","A rough graph or diagram showing the correct shape and labelled axes","Labels matter"]]},{"type":"h","text":"2. The P–R–L method for every 'explain'"},{"type":"steps","items":["**Point** — say what happens (the observation).","**Reason** — the physics idea: a law, a particle idea, a definition (Newton's laws, kinetic theory, electrons, TIR…).","**Link** — connect the reason back to the question ('…so the pressure increases')."]},{"type":"tip","text":"Use the **key words** the mark scheme is looking for. In these model answers they are in **bold**. Learn them — if your answer is missing the key word, you usually lose the mark."},{"type":"warn","text":"Writing vague words like 'the energy goes away', 'the particles get excited', 'it becomes charged', 'the light bends'. Be exact: '**electrons** are transferred', 'molecules gain **kinetic energy**', 'light **refracts towards the normal**'."},{"type":"h","text":"3. The 20 most common explain/describe questions — model answers"},{"type":"p","text":"These 20 come up again and again across Sections A–E. Read each question, cover the answer, try it aloud, then check. The (1) shows where each mark is earned."},{"type":"p","text":"**E1 (Section A) — Explain why a passenger who is not wearing a seatbelt is thrown forward when a car brakes suddenly.** *[3 marks]*"},{"type":"remember","text":"When the car stops, the passenger's body **continues moving forward** at the original speed (1). This is **inertia** — Newton's first law: a body keeps its state of uniform motion unless a resultant force acts on it (1). A seatbelt supplies the backward force that slows the passenger down with the car (1).","label":"MODEL ANSWER E1"},{"type":"p","text":"**E2 (Section A) — Explain, using Newton's third law, how a rocket is pushed upwards.** *[3 marks]*"},{"type":"remember","text":"The rocket engine pushes hot exhaust gases **downwards / backwards** with a large force (1). By Newton's third law, the gases push the rocket **upwards with an equal and opposite force** (1). When this upward force is greater than the rocket's weight, there is a resultant upward force, so the rocket accelerates upwards ⟪(F=ma)⟫ (1).","label":"MODEL ANSWER E2"},{"type":"p","text":"**E3 (Section A) — Explain why a racing car is built with a low centre of gravity and a wide wheel base.** *[3 marks]*"},{"type":"remember","text":"An object is stable if, when tilted, the line of action of its weight still falls **inside its base** (1). A low centre of gravity and a wide base mean the car must tilt through a **much larger angle** before the weight acts outside the base (1). Until then the weight gives a **moment that turns the car back** to its original position, so it does not topple when cornering (1).","label":"MODEL ANSWER E3"},{"type":"p","text":"**E4 (Section A) — A solid steel bar sinks in water, but a ship made of steel floats. Explain why.** *[3 marks]*"},{"type":"remember","text":"The ship is hollow (full of air), so it **displaces a very large volume of water** (1). By **Archimedes' principle**, the upthrust equals the **weight of water displaced** (1). The ship sinks only until the upthrust equals its weight; its **average density** (steel + air) is less than that of water, so it floats. The solid bar displaces only its own small volume, so its weight is greater than the upthrust (1).","label":"MODEL ANSWER E4"},{"type":"p","text":"**E5 (Section A) — Describe the energy changes in a hydroelectric power station and give ONE reason why it is a good energy source for some Caribbean countries.** *[4 marks]*"},{"type":"remember","text":"Water stored high behind a dam has **gravitational potential energy** (1). As it falls down the pipes, PE changes to **kinetic energy** (1). The moving water turns a **turbine**, which drives a **generator** that changes kinetic energy into **electrical energy** (1). Reason: it is **renewable** / produces no greenhouse gases / reduces costly imports of fossil fuel — suited to countries with high rainfall and rivers, e.g. Guyana, Suriname, Dominica (1).","label":"MODEL ANSWER E5"},{"type":"p","text":"**E6 (Section B) — Explain, using the kinetic theory, why the pressure of a gas in a closed rigid container increases when the gas is heated.** *[3 marks]*"},{"type":"remember","text":"Heating gives the gas molecules more **kinetic energy**, so they move **faster** (1). They collide with the walls **more often** (1) and **with greater force** (bigger change of momentum), so the force per unit area — the pressure — increases (1).","label":"MODEL ANSWER E6"},{"type":"p","text":"**E7 (Section B) — Explain why the temperature of ice stays at 0 °C while it is melting, even though it is being heated.** *[3 marks]*"},{"type":"remember","text":"The energy supplied is **latent heat** (1). It is used to **break (weaken) the bonds** between the molecules, increasing their potential energy, so the solid can become a liquid (1). The **kinetic energy** of the molecules does not increase, and temperature measures average KE, so the temperature stays constant (1).","label":"MODEL ANSWER E7"},{"type":"p","text":"**E8 (Section B) — Explain how a vacuum flask keeps a hot drink hot.** *[4 marks]*"},{"type":"remember","text":"The **vacuum** between the double walls has no particles, so it stops heat transfer by **conduction** (1) and by **convection** (1). The **silvered surfaces** of the walls reflect **radiation** back towards the drink (1). The insulating **stopper** (plastic/cork) reduces conduction and convection (and evaporation) through the top (1).","label":"MODEL ANSWER E8"},{"type":"p","text":"**E9 (Section B) — Explain how a sea breeze is formed on a sunny day at the beach.** *[4 marks]*"},{"type":"remember","text":"During the day the **land heats up faster** than the sea (the sea has a higher specific heat capacity) (1). Air above the land is warmed, **expands, becomes less dense and rises** (1). **Cooler, denser air from over the sea** moves in to take its place — this is the sea breeze (1). The air cools and sinks over the sea, completing a **convection current** (1).","label":"MODEL ANSWER E9"},{"type":"p","text":"**E10 (Section C) — Explain why sound cannot travel through a vacuum but light can. Describe ONE experiment that shows this.** *[4 marks]*"},{"type":"remember","text":"Sound is a **mechanical (longitudinal) wave** — it needs **particles** to vibrate and pass on the compressions and rarefactions (1). A vacuum has no particles, so sound cannot pass (1). Light is an **electromagnetic wave**, which needs no medium (1). Experiment: an electric bell in a **bell jar** — as the air is pumped out the sound fades away, but the bell can still be **seen** ringing (1).","label":"MODEL ANSWER E10"},{"type":"p","text":"**E11 (Section C) — Explain how light travels along a curved optical fibre.** *[4 marks]*"},{"type":"remember","text":"Light inside the glass core strikes the boundary with the cladding/air, travelling from a **denser to a less dense** medium (1). The angle of incidence is **greater than the critical angle** (1), so **total internal reflection** occurs — all the light is reflected, none escapes (1). Repeated total internal reflections carry the light along the fibre, even round bends (e.g. endoscopes, telephone/internet cables) (1).","label":"MODEL ANSWER E11"},{"type":"p","text":"**E12 (Section C) — Explain why a swimming pool looks shallower than it really is.** *[3 marks]*"},{"type":"remember","text":"Light from the bottom of the pool passes from water into air, **speeds up and refracts away from the normal** at the surface (1). The eye/brain assumes light travels in **straight lines**, so it traces the rays back (1). The rays seem to come from a point **higher than the real bottom**, so the apparent depth is less than the real depth (1).","label":"MODEL ANSWER E12"},{"type":"p","text":"**E13 (Section C) — Distinguish between a transverse wave and a longitudinal wave, giving ONE example of each.** *[4 marks]*"},{"type":"remember","text":"Transverse: the particles vibrate **at right angles (perpendicular)** to the direction the wave travels / energy is transferred (1), e.g. light, any EM wave, water waves (1). Longitudinal: the particles vibrate **parallel** to the direction of travel, forming **compressions and rarefactions** (1), e.g. sound (1).","label":"MODEL ANSWER E13"},{"type":"p","text":"**E14 (Section D) — A balloon is rubbed on a woollen jumper and then sticks to a neutral wall. Explain why.** *[3 marks]*"},{"type":"remember","text":"Rubbing transfers **electrons** from the wool to the balloon, so the balloon becomes **negative** (1). Near the wall, the balloon **repels electrons** in the wall away from the surface, leaving the near surface **positive** (charge by induction) (1). The unlike charges are **closer** than the like charges, so the **attraction is greater than the repulsion** and the balloon sticks (1).","label":"MODEL ANSWER E14"},{"type":"p","text":"**E15 (Section D) — Give THREE reasons why appliances in a house are connected in parallel.** *[3 marks]*"},{"type":"remember","text":"Each appliance gets the **full mains voltage** (1). Each can be **switched on and off independently** (1). If one appliance breaks / its fuse blows, the **others keep working** (1).","label":"MODEL ANSWER E15"},{"type":"p","text":"**E16 (Section D) — Explain how a fuse and the earth wire together protect a person using a kettle with a metal case.** *[4 marks]*"},{"type":"remember","text":"The fuse is a **thin wire with a low melting point** placed in the **live** wire (1). If the current is larger than the fuse rating, the wire **melts** and breaks the circuit (1). The earth wire connects the **metal case** to the ground (1). If the live wire touches the case, a **large current flows to earth** through the low-resistance earth wire, which blows the fuse, so the case does not stay live and the user does not get a shock (1).","label":"MODEL ANSWER E16"},{"type":"p","text":"**E17 (Section D) — Explain how a simple d.c. motor keeps turning in the same direction.** *[4 marks]*"},{"type":"remember","text":"A current flows in the coil, which is in a **magnetic field**, so a **force acts on each side** of the coil (motor effect) (1). The currents in the two sides are in **opposite directions**, so the forces are opposite (Fleming's left-hand rule), giving a **turning effect (couple)** (1). The **split-ring commutator reverses the current** in the coil every half turn (1), so the forces keep turning the coil the **same way** (1).","label":"MODEL ANSWER E17"},{"type":"p","text":"**E18 (Section D) — Explain how a transformer works and why electricity is transmitted at a very high voltage.** *[4 marks]*"},{"type":"remember","text":"An **alternating current** in the primary coil produces a **changing magnetic field (flux)** in the iron core (1). This changing flux passes through the secondary coil and **induces an alternating e.m.f.** in it (1). A step-up transformer raises the voltage, so for the same power ⟪(P=IV)⟫ the **current is much smaller** (1). Smaller current means **less energy is lost as heat** in the cables (power loss ⟪=I^{2}R⟫) (1).","label":"MODEL ANSWER E18"},{"type":"p","text":"**E19 (Section E) — Describe the Geiger–Marsden (gold foil) experiment and explain what it showed about the atom.** *[4 marks]*"},{"type":"remember","text":"**Alpha particles** were fired at a very thin **gold foil** in a vacuum (1). **Most went straight through**, so the atom is **mostly empty space** (1). A few were **deflected through large angles**, so there is a small, concentrated **positive charge** (1). Very few (about 1 in 8000) **bounced back**, so almost all the mass is in a **tiny, dense nucleus** (1).","label":"MODEL ANSWER E19"},{"type":"p","text":"**E20 (Section E) — Explain why a gamma emitter with a half-life of about 6 hours is chosen as a medical tracer.** *[3 marks]*"},{"type":"remember","text":"Gamma rays are **very penetrating**, so they pass out of the body and can be **detected outside** (1). Gamma is **weakly ionising**, so it causes less damage to cells than alpha or beta (1). A **short half-life** means the activity falls quickly so the patient is not exposed for long, but 6 hours is long enough to **complete the scan** (1).","label":"MODEL ANSWER E20"},{"type":"table","headers":["Section","Model answers","Share of the 20"],"rows":[["A Mechanics","E1–E5","5"],["B Thermal physics","E6–E9","4"],["C Waves & optics","E10–E13","4"],["D Electricity & magnetism","E14–E18","5"],["E The atom","E19–E20","2"]]}],"examples":[{"id":"week14.2.e1","title":"Turning a 1-mark answer into a 3-mark answer (Section B)","question":"Explain why a metal spoon feels colder than a plastic spoon, although both are at room temperature. [3]","steps":[{"label":"Weak answer","text":"'Because the metal is colder.' — 0 marks: it is WRONG (both are at the same temperature) and gives no physics."},{"label":"Point","text":"Metal is a good **conductor** of heat; plastic is an **insulator**. (1)"},{"label":"Reason","text":"The metal **conducts heat away from your hand quickly** (free electrons carry the energy). (1)"},{"label":"Link","text":"Your hand loses heat faster to the metal, so your skin cools and the metal **feels** colder. (1)"}],"answer":"Metal conducts heat away from the hand faster than plastic, so the hand loses heat faster and the metal feels colder — but both are at the same temperature."},{"id":"week14.2.e2","title":"A 'describe an experiment' answer (Section E)","question":"Describe an experiment to show that alpha particles are stopped by a sheet of paper but beta particles are not. [4]","steps":[{"label":"Set-up","text":"Place a GM tube connected to a counter close (about 2 cm) to the source. First measure the **background count** with no source. (1)"},{"label":"Step","text":"Measure the count rate with the alpha source and no absorber, then with a **sheet of paper** between source and tube. (1)"},{"label":"Observation","text":"With paper, the count rate falls to **background**, so alpha is stopped by paper. (1)"},{"label":"Compare","text":"Repeat with the beta source: the count rate with paper stays well above background; it needs **a few mm of aluminium** to stop it. Handle sources with **tongs**. (1)"}],"answer":"GM tube + counter, background count, compare count rates with and without paper for alpha and beta sources; alpha drops to background, beta does not."}]},"tryit":[{"id":"week14.2.p1","kind":"self","q":"Explain, in terms of molecules, why evaporation causes cooling (e.g. sweating).","marks":3,"level":2,"lines":4,"scheme":"The **faster / most energetic** molecules at the surface escape (1). The molecules left behind have a **lower average kinetic energy** (1). Temperature depends on average KE, so the liquid (and the skin) cools (1).","points":[{"text":"The **faster / most energetic** molecules at the surface escape","marks":1},{"text":"The molecules left behind have a **lower average kinetic energy**","marks":1},{"text":"Temperature depends on average KE, so the liquid (and the skin) cools","marks":1}],"section":"try"},{"id":"week14.2.p2","kind":"self","q":"Give THREE differences between evaporation and boiling.","marks":3,"level":2,"lines":4,"scheme":"Any three (1 each): evaporation happens at **any temperature**, boiling only at the **boiling point**; evaporation occurs only at the **surface**, boiling **throughout** the liquid (bubbles); evaporation causes **cooling**, boiling happens at constant temperature while heat is supplied; evaporation is **slow/quiet**, boiling is rapid.","points":[{"text":"Any three (1 each): evaporation happens at **any temperature**, boiling only at the **boiling point**; evaporation occurs only at the **surface**, boiling **throughout** the liquid (bubbles); evaporation causes **cooling**, boiling happens at constant temperature while heat is supplied; evaporation is **slow/quiet**, boiling is rapid.","marks":3,"each":true}],"section":"try"}],"practice":[{"id":"week14.2.p3","kind":"self","q":"Explain why small gaps are left between sections of railway line.","marks":2,"level":2,"lines":3,"scheme":"Steel **expands** when heated on hot days (1); the gaps leave room for expansion so the rails do not **buckle** (1).","points":[{"text":"Steel **expands** when heated on hot days","marks":1},{"text":"the gaps leave room for expansion so the rails do not **buckle**","marks":1}],"section":"practice"},{"id":"week14.2.p4","kind":"self","q":"Explain why cars are built with crumple zones at the front.","marks":3,"level":2,"lines":4,"scheme":"In a crash the car (and passengers) must lose all their momentum (1). The crumple zone makes the car stop over a **longer time** (1), so the deceleration is smaller and, from ⟪F=ma⟫, the **force** on the passengers is smaller (1).","points":[{"text":"In a crash the car (and passengers) must lose all their momentum","marks":1},{"text":"The crumple zone makes the car stop over a **longer time**","marks":1},{"text":"so the deceleration is smaller and, from ⟪F=ma⟫, the **force** on the passengers is smaller","marks":1}],"section":"practice"},{"id":"week14.2.p5","kind":"self","q":"During a thunderstorm you see the lightning before you hear the thunder. Explain why.","marks":2,"level":2,"lines":3,"scheme":"Both are produced at the same time (1), but light travels much faster ⟪(3\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫ than sound ⟪(\\approx 340\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫, so light arrives first (1).","points":[{"text":"Both are produced at the same time","marks":1},{"text":"but light travels much faster ⟪(3\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫ than sound ⟪(\\approx 340\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫, so light arrives first","marks":1}],"section":"practice"},{"id":"week14.2.p6","kind":"self","q":"Explain why soft iron, not steel, is used as the core of an electromagnet in an electric bell.","marks":2,"level":2,"lines":3,"scheme":"Soft iron is a **temporary** magnet — it is easily magnetised and **loses its magnetism** as soon as the current is switched off (1); steel would stay magnetised, so the bell's armature would not be released (1).","points":[{"text":"Soft iron is a **temporary** magnet — it is easily magnetised and **loses its magnetism** as soon as the current is switched off","marks":1},{"text":"steel would stay magnetised, so the bell's armature would not be released","marks":1}],"section":"practice"}],"exit":[{"id":"week14.2.p7","kind":"self","q":"Explain why changing the temperature or pressure of a radioactive sample does not change its half-life.","marks":2,"level":2,"lines":3,"scheme":"Radioactive decay is a process in the **nucleus** (1); it is random and spontaneous and is not affected by physical or chemical conditions outside the nucleus (1).","points":[{"text":"Radioactive decay is a process in the **nucleus**","marks":1},{"text":"it is random and spontaneous and is not affected by physical or chemical conditions outside the nucleus","marks":1}],"section":"exit"},{"id":"week14.2.p8","kind":"self","q":"Explain why a bird can stand on a high-voltage cable without getting a shock.","marks":2,"level":2,"lines":3,"scheme":"Both feet are on the same wire, at (almost) the **same potential**, so there is no p.d. across the bird (1); therefore (almost) no current flows through its body (1).","points":[{"text":"Both feet are on the same wire, at (almost) the **same potential**, so there is no p.d. across the bird","marks":1},{"text":"therefore (almost) no current flows through its body","marks":1}],"section":"exit"}],"warmup":[{"id":"week14.2.w1","kind":"self","q":"The x-values in a table go from 0 to 4.6 N and the y-values from 0 to 37 cm. The grid is 16 big squares wide and 12 big squares tall. Choose a suitable scale for each axis and show that your graph covers more than half the grid.","marks":2,"level":2,"lines":3,"scheme":"x: 0.5 N per big square → 4.6 N uses 9.2 of 16 squares (> 8, more than half) (1); y: 5 cm per big square → 37 cm uses 7.4 of 12 squares (> 6) (1). (Do not accept scales of 3, 6, 7 or 9 units per square.)","points":[{"text":"x: 0.5 N per big square → 4.6 N uses 9.2 of 16 squares (> 8, more than half)","marks":1},{"text":"y: 5 cm per big square → 37 cm uses 7.4 of 12 squares (> 6) (Do not accept scales of 3, 6, 7 or 9 units per square.)","marks":1}],"section":"warmup","src":"week14.1.p3"},{"id":"week14.2.w2","kind":"self","q":"Give ONE source of error and ONE matching precaution for each experiment: (a) timing a pendulum (b) reading a measuring cylinder (c) measuring a radioactive count rate (d) finding the specific heat capacity of a metal block.","marks":4,"level":3,"lines":5,"scheme":"(a) Reaction time → time 20 oscillations / repeat and average (1). (b) Parallax → eye level with bottom of meniscus (1). (c) Random decay/background radiation → repeat counts, subtract background (1). (d) Heat lost to surroundings → insulate (lag) the block / use oil in the thermometer hole (1).","points":[{"text":"(a) Reaction time → time 20 oscillations / repeat and average","marks":1},{"text":"(b) Parallax → eye level with bottom of meniscus","marks":1},{"text":"(c) Random decay/background radiation → repeat counts, subtract background","marks":1},{"text":"(d) Heat lost to surroundings → insulate (lag) the block / use oil in the thermometer hole","marks":1}],"section":"warmup","src":"week14.1.p12"},{"id":"week14.2.w3","kind":"self","q":"State the number of significant figures in (i) 0.0450 (ii) ⟪3.20\\times 10^{3}⟫ (iii) 400.5. (iv) Round 2.3468 to 3 s.f.","marks":4,"level":3,"lines":2,"scheme":"(i) 3 (1)  (ii) 3 (1)  (iii) 4 (1)  (iv) 2.35 (1).","points":[{"text":"(i) 3","marks":1},{"text":"(ii) 3","marks":1},{"text":"(iii) 4","marks":1},{"text":"(iv) 2.35","marks":1}],"section":"warmup","src":"week14.1.p1"}],"n":102},{"id":"week14.3A","kind":"unit","unit":"3A","title":"Calculation Bank (1): Mechanics","titleText":"Calculation Bank (1): Mechanics","goals":[{"code":"A","text":"Section A — Mechanics: scientific method & graphs, measurement, vectors, statics (moments, Hooke), dynamics (Newton, momentum), energy & power, hydrostatics"}],"codes":["A"],"words":[],"learn":{"notes":[{"type":"p","text":"This bank covers **every formula you need for Paper 02**, with one worked example and two practice questions each (F1–F29 across Units 3A–3C). Section A (Mechanics) has the most formulas, so it comes first. The general method is always the same:"},{"type":"steps","items":["Write the **formula** in symbols.","**Convert** units (g → kg, cm → m, minutes → s, kW → W) BEFORE you substitute.","**Substitute** the numbers.","Calculate and write the **answer with its unit**, rounded to 2–3 s.f."]},{"type":"table","headers":["Code","Formula","Notes"],"rows":[["F1","⟪\\rho =m\\div V⟫","ρ in kg m^−3^ (or g cm^−3^); m in kg (g); V in m^3^ (cm^3^). ⟪1\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"],["F2","moment ⟪=F\\times d⟫;  sum of clockwise moments = sum of anticlockwise moments (in equilibrium)","F in N; d = perpendicular distance from the pivot, in m (or cm); moment in N m (N cm)"],["F3","⟪F=kx⟫","F = force (N); x = extension (m); k = spring constant (N m^−1^). Only up to the limit of proportionality"],["F4","⟪a=(v-u)\\div t⟫;  ⟪v=u⟫ + at;  distance = area under a v–t graph","u = initial velocity, v = final velocity (m s^−1^); t in s; a in m s^−2^"],["F5","⟪F=ma⟫;  ⟪W=mg⟫","F = RESULTANT force (N); m in kg; a in m s^−2^; ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫ on Earth"],["F6","⟪p=mv⟫;  total momentum before = total momentum after","p in kg m s^−1^; m in kg; v in m s^−1^ (direction matters)"],["F7","⟪W=F\\times d⟫;  ⟪P=E\\div t\\ (=W\\div t)⟫","W in J; F in N; d = distance moved in the direction of the force (m); P in W; t in s"],["F8","⟪E_{p}=mgh⟫;  ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫;  (energy is conserved: loss of PE = gain of KE)","E in J; m in kg; h in m; v in m s^−1^"],["F9","efficiency = (useful energy output ÷ total energy input) × 100 %","Same for power: useful power out ÷ power in × 100 %. Always less than 100 %"],["F10","⟪P=F\\div A⟫","P in ⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫; F in N; A in m^2^. ⟪1\\,\\mathrm{cm}^{2}=1\\times 10^{-4}\\,\\mathrm{m}^{2}⟫"],["F11","⟪P=\\rho gh⟫","ρ = density of liquid (kg m^−3^); ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫; h = depth (m); P in Pa"]]},{"type":"remember","text":"Every calculation: **Formula → Substitute (with units converted) → Answer with unit**, 2–3 s.f. Even if your final answer is wrong, the formula and substitution usually earn marks."},{"type":"tip","text":"Practise in this order: cover the worked example, try it yourself, check, then do the two practice questions marked with the same code (e.g. [F7])."}],"examples":[{"id":"week14.3A.e1","title":"F1 Density","question":"A metal block measures ⟪2.0\\,\\mathrm{cm}\\times 3.0\\,\\mathrm{cm}\\times 5.0\\,\\mathrm{cm}⟫ and has a mass of 81 g. Find its density in g cm^−3^ and kg m^−3^.","steps":[{"label":"Volume","text":"⟪V=2.0\\times 3.0\\times 5.0=30\\,\\mathrm{cm}^{3}⟫"},{"label":"Formula","text":"⟪\\rho =m\\div V⟫"},{"label":"Substitute","text":"⟪\\rho =81\\div 30⟫"},{"label":"Calculate","text":"⟪\\rho =2.7\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=2700\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"}],"answer":"⟪2.7\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}=2.7\\times 10^{3}\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (aluminium)"},{"id":"week14.3A.e2","title":"F2 Principle of moments","question":"A light metre rule is pivoted at its centre (50 cm). A 3.0 N weight hangs at the 10 cm mark. What weight W at the 80 cm mark balances it?","img":{"src":"img/week14/moments","alt":"A light metre rule is pivoted at its centre (50 cm). A 3.0 N weight hangs at the 10 cm mark. What weight W at the 80 cm mark balances it?","w":703,"h":414},"steps":[{"label":"Distances","text":"3.0 N is 40 cm from the pivot; W is 30 cm from the pivot."},{"label":"Formula","text":"anticlockwise moment = clockwise moment"},{"label":"Substitute","text":"⟪3.0\\times 40=W\\times 30⟫"},{"label":"Calculate","text":"⟪W=120\\div 30=4.0\\,\\mathrm{N}⟫"}],"answer":"⟪W=4.0\\,\\mathrm{N}⟫"},{"id":"week14.3A.e3","title":"F3 Hooke's law","question":"A spring extends by 4.0 cm when a 2.0 N load hangs on it. Find (a) the spring constant (b) the extension for a 3.5 N load.","steps":[{"label":"Formula","text":"⟪k=F\\div x⟫"},{"label":"Substitute","text":"⟪k=2.0\\div 4.0=0.50\\,\\mathrm{N}\\,\\mathrm{cm}^{-1}\\ (=50\\,\\mathrm{N}\\,\\mathrm{m}^{-1})⟫"},{"label":"(b)","text":"⟪x=F\\div k=3.5\\div 0.50⟫"},{"label":"Calculate","text":"⟪x=7.0\\,\\mathrm{cm}⟫"}],"answer":"(a) ⟪0.50\\,\\mathrm{N}\\,\\mathrm{cm}^{-1}=50\\,\\mathrm{N}\\,\\mathrm{m}^{-1}⟫ (b) 7.0 cm"},{"id":"week14.3A.e4","title":"F4 Acceleration","question":"A car speeds up from 5.0 m s^−1^ to 25 m s^−1^ in 8.0 s. Find its acceleration.","steps":[{"label":"Formula","text":"⟪a=(v-u)\\div t⟫"},{"label":"Substitute","text":"⟪a=(25-5.0)\\div 8.0=20\\div 8.0⟫"},{"label":"Calculate","text":"⟪a=2.5\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫"}],"answer":"2.5 m s^−2^"},{"id":"week14.3A.e5","title":"F5 Resultant force","question":"A 1200 kg car has a driving force of 3000 N and friction of 600 N acting on it. Find its acceleration.","steps":[{"label":"Resultant","text":"⟪F=3000-600=2400\\,\\mathrm{N}⟫"},{"label":"Formula","text":"⟪a=F\\div m⟫"},{"label":"Substitute","text":"⟪a=2400\\div 1200⟫"},{"label":"Calculate","text":"⟪a=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫"}],"answer":"2.0 m s^−2^"},{"id":"week14.3A.e6","title":"F6 Collision","question":"A 2.0 kg trolley moving at 3.0 m s^−1^ hits a stationary 1.0 kg trolley and they stick together. Find their common velocity.","steps":[{"label":"Before","text":"⟪p=2.0\\times 3.0+1.0\\times 0=6.0\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"},{"label":"After","text":"⟪p=(2.0+1.0)\\times v=3.0v⟫"},{"label":"Conservation","text":"⟪3.0v=6.0⟫"},{"label":"Calculate","text":"⟪v=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ in the original direction"}],"answer":"2.0 m s^−1^"},{"id":"week14.3A.e7","title":"F7 Work and power","question":"A crane lifts a 500 kg load through 12 m in 20 s. Find the work done and the power.","steps":[{"label":"Force","text":"⟪F=mg=500\\times 10=5000\\,\\mathrm{N}⟫"},{"label":"Work","text":"⟪W=Fd=5000\\times 12=60\\,000\\,\\mathrm{J}⟫"},{"label":"Power","text":"⟪P=W\\div t=60\\,000\\div 20⟫"},{"label":"Calculate","text":"⟪P=3000\\,\\mathrm{W}\\ (3.0\\,\\mathrm{kW})⟫"}],"answer":"Work ⟪=6.0\\times 10^{4}\\,\\mathrm{J}⟫; power ⟪=3.0\\,\\mathrm{kW}⟫"},{"id":"week14.3A.e8","title":"F8 Energy conservation","question":"A 2.0 kg ball is dropped from 5.0 m. Ignoring air resistance, find (a) its PE at the top (b) its speed just before it lands.","steps":[{"label":"(a)","text":"⟪E_{p}=mgh=2.0\\times 10\\times 5.0=100\\,\\mathrm{J}⟫"},{"label":"(b) Formula","text":"KE at bottom ⟪=PE⟫ at top: ⟪\\tfrac{1}{2}mv^{2}=100⟫"},{"label":"Substitute","text":"⟪\\tfrac{1}{2}\\times 2.0\\times v^{2}=100\\rightarrow v^{2}=100⟫"},{"label":"Calculate","text":"⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"(a) 100 J (b) 10 m s^−1^"},{"id":"week14.3A.e9","title":"F9 Efficiency","question":"An electric motor uses 500 J of electrical energy to give 360 J of useful work. Find its efficiency.","steps":[{"label":"Formula","text":"efficiency = useful out ÷ input × 100 %"},{"label":"Substitute","text":"⟪=360\\div 500\\times 100\\%⟫"},{"label":"Calculate","text":"efficiency ⟪=72\\%⟫"}],"answer":"72 % (the other 140 J is wasted as heat and sound)"},{"id":"week14.3A.e10","title":"F10 Pressure","question":"A 600 N woman stands on one stiletto heel of area 1.0 cm^2^. Find the pressure on the floor.","steps":[{"label":"Convert","text":"⟪A=1.0\\,\\mathrm{cm}^{2}=1.0\\times 10^{-4}\\,\\mathrm{m}^{2}⟫"},{"label":"Formula","text":"⟪P=F\\div A⟫"},{"label":"Substitute","text":"⟪P=600\\div 1.0\\times 10^{-4}⟫"},{"label":"Calculate","text":"⟪P=6.0\\times 10^{6}\\,\\mathrm{Pa}⟫"}],"answer":"⟪6.0\\times 10^{6}\\,\\mathrm{Pa}⟫"},{"id":"week14.3A.e11","title":"F11 Liquid pressure","question":"Find the pressure due to the water at the bottom of a tank 8.0 m deep ⟪(\\rho =1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫.","steps":[{"label":"Formula","text":"⟪P=\\rho gh⟫"},{"label":"Substitute","text":"⟪P=1000\\times 10\\times 8.0⟫"},{"label":"Calculate","text":"⟪P=80\\,000\\,\\mathrm{Pa}=8.0\\times 10^{4}\\,\\mathrm{Pa}⟫"}],"answer":"⟪8.0\\times 10^{4}\\,\\mathrm{Pa}\\ (80\\,\\mathrm{kPa})⟫"}]},"tryit":[{"id":"week14.3A.p1","kind":"num","q":"**[F1]** A stone of mass 60 g is lowered into a measuring cylinder. The water level rises from 40.0 cm^3^ to 64.0 cm^3^. Calculate the density of the stone.","marks":2,"level":2,"lines":3,"scheme":"⟪V=64.0-40.0=24.0\\,\\mathrm{cm}^{3}⟫ (1); ⟪\\rho =60\\div 24.0=2.5\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}\\ (2500\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫ (1).","points":[{"text":"⟪V=64.0-40.0=24.0\\,\\mathrm{cm}^{3}⟫","marks":1},{"text":"⟪\\rho =60\\div 24.0=2.5\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}\\ (2500\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫","marks":1}],"num":{"value":2.5,"sf":2,"unit":"g cm^−3^","unitTex":"\\mathrm{g}\\,\\mathrm{cm}^{-3}","alt":[2500]},"section":"try","hint":{"text":"Look back at Example 1 (F1 Density). Start like this: Volume: ⟪V=2.0\\times 3.0\\times 5.0=30\\,\\mathrm{cm}^{3}⟫","from":1}},{"id":"week14.3A.p2","kind":"num","q":"**[F1]** Cooking oil has a density of 0.80 g cm^−3^. Find the mass of 250 cm^3^ of oil.","marks":2,"level":2,"lines":2,"scheme":"⟪m=\\rho V⟫ (1) ⟪=0.80\\times 250=200\\,\\mathrm{g}\\ (0.20\\,\\mathrm{kg})⟫ (1).","points":[{"text":"⟪m=\\rho V⟫","marks":1},{"text":"⟪=0.80\\times 250=200\\,\\mathrm{g}\\ (0.20\\,\\mathrm{kg})⟫","marks":1}],"num":{"value":200,"sf":1,"unit":"g","unitTex":"\\mathrm{g}","alt":[0.2]},"section":"try","hint":{"text":"Look back at Example 1 (F1 Density). Start like this: Volume: ⟪V=2.0\\times 3.0\\times 5.0=30\\,\\mathrm{cm}^{3}⟫","from":1}}],"practice":[{"id":"week14.3A.p3","kind":"num","q":"**[F2]** A 300 N child sits 2.0 m from the pivot of a see-saw. How far from the pivot, on the other side, must a 400 N child sit to balance?","marks":2,"level":2,"lines":3,"scheme":"⟪300\\times 2.0=400\\times d⟫ (1); ⟪d=600\\div 400=1.5\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪300\\times 2.0=400\\times d⟫","marks":1},{"text":"⟪d=600\\div 400=1.5\\,\\mathrm{m}⟫","marks":1}],"num":{"value":1.5,"sf":2,"unit":"m","unitTex":"\\mathrm{m}"},"section":"practice","hint":{"text":"Look back at Example 4 (F4 Acceleration). Start like this: Formula: ⟪a=(v-u)\\div t⟫","from":4}},{"id":"week14.3A.p4","kind":"self","q":"**[F2]** A uniform metre rule of weight 1.2 N is pivoted at the 30 cm mark. Where must a 2.0 N weight be hung to keep it balanced?","marks":3,"level":2,"lines":4,"scheme":"Weight of the rule acts at its centre, 50 cm mark, 20 cm from pivot: moment ⟪=1.2\\times 20=24\\,\\mathrm{N}\\,\\mathrm{cm}⟫ (1). ⟪2.0\\times d=24⟫, ⟪d=12\\,\\mathrm{cm}⟫ (1), on the other side of the pivot, i.e. at the 18 cm mark (1).","points":[{"text":"Weight of the rule acts at its centre, 50 cm mark, 20 cm from pivot: moment ⟪=1.2\\times 20=24\\,\\mathrm{N}\\,\\mathrm{cm}⟫","marks":1},{"text":"⟪2.0\\times d=24⟫, ⟪d=12\\,\\mathrm{cm}⟫","marks":1},{"text":"on the other side of the pivot, i.e. at the 18 cm mark","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (F2 Principle of moments). Start like this: Distances: 3.0 N is 40 cm from the pivot; W is 30 cm from the pivot.","from":2}},{"id":"week14.3A.p5","kind":"num","q":"**[F3]** A spring has ⟪k=200\\,\\mathrm{N}\\,\\mathrm{m}^{-1}⟫. What force stretches it by 0.15 m?","marks":2,"level":2,"lines":2,"scheme":"⟪F=kx⟫ (1) ⟪=200\\times 0.15=30\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪F=kx⟫","marks":1},{"text":"⟪=200\\times 0.15=30\\,\\mathrm{N}⟫","marks":1}],"num":{"value":30,"sf":1,"unit":"N","unitTex":"\\mathrm{N}"},"section":"practice","hint":{"text":"Look back at Example 2 (F2 Principle of moments). Start like this: Distances: 3.0 N is 40 cm from the pivot; W is 30 cm from the pivot.","from":2}},{"id":"week14.3A.p6","kind":"num","q":"**[F3]** A spring of natural length 12.0 cm is 15.0 cm long with a 6.0 N load. Find its length with a 10 N load (it obeys Hooke's law).","marks":3,"level":2,"lines":4,"scheme":"Extension ⟪=3.0\\,\\mathrm{cm}⟫, so ⟪k=6.0\\div 3.0=2.0\\,\\mathrm{N}\\,\\mathrm{cm}^{-1}⟫ (1); new extension ⟪=10\\div 2.0=5.0\\,\\mathrm{cm}⟫ (1); length ⟪=12.0+5.0=17.0\\,\\mathrm{cm}⟫ (1).","points":[{"text":"Extension ⟪=3.0\\,\\mathrm{cm}⟫, so ⟪k=6.0\\div 3.0=2.0\\,\\mathrm{N}\\,\\mathrm{cm}^{-1}⟫","marks":1},{"text":"new extension ⟪=10\\div 2.0=5.0\\,\\mathrm{cm}⟫","marks":1},{"text":"length ⟪=12.0+5.0=17.0\\,\\mathrm{cm}⟫","marks":1}],"num":{"value":17,"sf":3,"unit":"cm","unitTex":"\\mathrm{cm}"},"conf":"low","section":"practice","hint":{"text":"Look back at Example 3 (F3 Hooke's law). Start like this: Formula: ⟪k=F\\div x⟫","from":3}},{"id":"week14.3A.p7","kind":"num","q":"**[F4]** A bus starts from rest and accelerates at 1.5 m s^−2^ for 12 s. Find its final velocity.","marks":2,"level":2,"lines":2,"scheme":"⟪v=u⟫ + at (1) ⟪=0+1.5\\times 12=18\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"⟪v=u⟫ + at","marks":1},{"text":"⟪=0+1.5\\times 12=18\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":18,"sf":2,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"section":"practice","hint":{"text":"Look back at Example 4 (F4 Acceleration). Start like this: Formula: ⟪a=(v-u)\\div t⟫","from":4}},{"id":"week14.3A.p8","kind":"self","q":"**[F4]** A car travelling at 30 m s^−1^ brakes uniformly to rest in 6.0 s. Find (a) its acceleration (b) the braking distance.","marks":3,"level":2,"lines":4,"scheme":"(a) a = (0 − 30) ÷ 6.0 = −5.0 m s^−2^ (a deceleration of 5.0 m s^−2^) (1). (b) distance = area under v–t graph ⟪=\\tfrac{1}{2}\\times 6.0\\times 30⟫ (1) ⟪=90\\,\\mathrm{m}⟫ (1).","points":[{"text":"(a) a = (0 − 30) ÷ 6.0 = −5.0 m s^−2^ (a deceleration of 5.0 m s^−2^)","marks":1},{"text":"(b) distance = area under v–t graph ⟪=\\tfrac{1}{2}\\times 6.0\\times 30⟫","marks":1},{"text":"⟪=90\\,\\mathrm{m}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (F4 Acceleration). Start like this: Formula: ⟪a=(v-u)\\div t⟫","from":4}},{"id":"week14.3A.p9","kind":"self","q":"**[F5]** An astronaut has a mass of 50 kg. Find her weight on Earth ⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫ and on the Moon ⟪(g=1.6\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫. What is her mass on the Moon?","marks":3,"level":2,"lines":3,"scheme":"Earth: ⟪W=50\\times 10=500\\,\\mathrm{N}⟫ (1); Moon: ⟪W=50\\times 1.6=80\\,\\mathrm{N}⟫ (1); mass is still 50 kg (1).","points":[{"text":"Earth: ⟪W=50\\times 10=500\\,\\mathrm{N}⟫","marks":1},{"text":"Moon: ⟪W=50\\times 1.6=80\\,\\mathrm{N}⟫","marks":1},{"text":"mass is still 50 kg","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (F1 Density). Start like this: Volume: ⟪V=2.0\\times 3.0\\times 5.0=30\\,\\mathrm{cm}^{3}⟫","from":1}},{"id":"week14.3A.p10","kind":"self","q":"**[F5]** What resultant force gives a 0.50 kg ball an acceleration of 12 m s^−2^?","marks":2,"level":2,"lines":2,"scheme":"⟪F=ma⟫ (1) ⟪=0.50\\times 12=6.0\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪F=ma⟫","marks":1},{"text":"⟪=0.50\\times 12=6.0\\,\\mathrm{N}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 5 (F5 Resultant force). Start like this: Resultant: ⟪F=3000-600=2400\\,\\mathrm{N}⟫","from":5}},{"id":"week14.3A.p11","kind":"num","q":"**[F6]** Calculate the momentum of a 70 kg sprinter running at 8.0 m s^−1^.","marks":2,"level":2,"lines":2,"scheme":"⟪p=mv⟫ (1) ⟪=70\\times 8.0=560\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"⟪p=mv⟫","marks":1},{"text":"⟪=70\\times 8.0=560\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":560,"sf":2,"unit":"kg m s^−1^","unitTex":"\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}"},"section":"practice"},{"id":"week14.3A.p12","kind":"self","q":"**[F6]** A 4.0 kg rifle fires a 0.010 kg bullet at 400 m s^−1^. Find the recoil velocity of the rifle.","marks":3,"level":2,"lines":3,"scheme":"Momentum before ⟪=0⟫ (1); ⟪0.010\\times 400=4.0\\times v⟫ (1); ⟪v=1.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ backwards (1).","points":[{"text":"Momentum before ⟪=0⟫","marks":1},{"text":"⟪0.010\\times 400=4.0\\times v⟫","marks":1},{"text":"⟪v=1.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ backwards","marks":1}],"section":"practice","hint":{"text":"Look back at Example 6 (F6 Collision). Start like this: Before: ⟪p=2.0\\times 3.0+1.0\\times 0=6.0\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","from":6}},{"id":"week14.3A.p13","kind":"num","q":"**[F7]** A box is pushed 4.0 m across a floor with a force of 150 N. Calculate the work done.","marks":2,"level":2,"lines":2,"scheme":"⟪W=Fd⟫ (1) ⟪=150\\times 4.0=600\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪W=Fd⟫","marks":1},{"text":"⟪=150\\times 4.0=600\\,\\mathrm{J}⟫","marks":1}],"num":{"value":600,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 7 (F7 Work and power). Start like this: Force: ⟪F=mg=500\\times 10=5000\\,\\mathrm{N}⟫","from":7}},{"id":"week14.3A.p14","kind":"num","q":"**[F7]** A 60 kg student runs up stairs 3.0 m high in 4.0 s. Calculate her power.","marks":3,"level":2,"lines":3,"scheme":"Work ⟪=mgh=60\\times 10\\times 3.0=1800\\,\\mathrm{J}⟫ (1); ⟪P=1800\\div 4.0⟫ (1) ⟪=450\\,\\mathrm{W}⟫ (1).","points":[{"text":"Work ⟪=mgh=60\\times 10\\times 3.0=1800\\,\\mathrm{J}⟫","marks":1},{"text":"⟪P=1800\\div 4.0⟫","marks":1},{"text":"⟪=450\\,\\mathrm{W}⟫","marks":1}],"num":{"value":450,"sf":2,"unit":"W","unitTex":"\\mathrm{W}"},"section":"practice"},{"id":"week14.3A.p15","kind":"num","q":"**[F8]** Find the kinetic energy of a 0.15 kg cricket ball moving at 20 m s^−1^.","marks":2,"level":2,"lines":2,"scheme":"⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫ (1) ⟪=\\tfrac{1}{2}\\times 0.15\\times 20^{2}=30\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫","marks":1},{"text":"⟪=\\tfrac{1}{2}\\times 0.15\\times 20^{2}=30\\,\\mathrm{J}⟫","marks":1}],"num":{"value":30,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 8 (F8 Energy conservation). Start like this: (a): ⟪E_{p}=mgh=2.0\\times 10\\times 5.0=100\\,\\mathrm{J}⟫","from":8}},{"id":"week14.3A.p16","kind":"self","q":"**[F8]** A 0.40 kg pendulum bob is pulled aside so that it rises 0.20 m. Find its maximum speed when released.","marks":3,"level":2,"lines":3,"scheme":"⟪PE=mgh=0.40\\times 10\\times 0.20=0.80\\,\\mathrm{J}⟫ (1); ⟪\\tfrac{1}{2}\\times 0.40\\times v^{2}=0.80\\rightarrow v^{2}=4.0⟫ (1); ⟪v=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1). (Mass cancels: ⟪v=\\sqrt{2gh}⟫.)","points":[{"text":"⟪PE=mgh=0.40\\times 10\\times 0.20=0.80\\,\\mathrm{J}⟫","marks":1},{"text":"⟪\\tfrac{1}{2}\\times 0.40\\times v^{2}=0.80\\rightarrow v^{2}=4.0⟫","marks":1},{"text":"⟪v=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (Mass cancels: ⟪v=\\sqrt{2gh}⟫.)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (F4 Acceleration). Start like this: Formula: ⟪a=(v-u)\\div t⟫","from":4}},{"id":"week14.3A.p17","kind":"num","q":"**[F9]** A 60 W filament lamp gives out 6.0 W of light. Find its efficiency.","marks":2,"level":2,"lines":2,"scheme":"⟪6.0\\div 60\\times 100\\%⟫ (1) ⟪=10\\%⟫ (1).","points":[{"text":"⟪6.0\\div 60\\times 100\\%⟫","marks":1},{"text":"⟪=10\\%⟫","marks":1}],"num":{"value":10,"sf":1,"unit":"%","unitTex":"\\%"},"section":"practice","hint":{"text":"Look back at Example 9 (F9 Efficiency). Start like this: Formula: efficiency = useful out ÷ input × 100 %","from":9}},{"id":"week14.3A.p18","kind":"self","q":"**[F9]** A pulley system is 80 % efficient. 2500 J of work is put in. How much useful work is done and how much is wasted?","marks":2,"level":2,"lines":3,"scheme":"Useful ⟪=0.80\\times 2500=2000\\,\\mathrm{J}⟫ (1); wasted ⟪=2500-2000=500\\,\\mathrm{J}⟫ (1).","points":[{"text":"Useful ⟪=0.80\\times 2500=2000\\,\\mathrm{J}⟫","marks":1},{"text":"wasted ⟪=2500-2000=500\\,\\mathrm{J}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 7 (F7 Work and power). Start like this: Force: ⟪F=mg=500\\times 10=5000\\,\\mathrm{N}⟫","from":7}},{"id":"week14.3A.p19","kind":"num","q":"**[F10]** A crate of weight 800 N rests on a base of area 0.40 m^2^. Find the pressure it exerts.","marks":2,"level":2,"lines":2,"scheme":"⟪P=F\\div A⟫ (1) ⟪=800\\div 0.40=2000\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪P=F\\div A⟫","marks":1},{"text":"⟪=800\\div 0.40=2000\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":2000,"sf":1,"unit":"Pa","unitTex":"\\mathrm{Pa}"},"section":"practice","hint":{"text":"Look back at Example 10 (F10 Pressure). Start like this: Convert: ⟪A=1.0\\,\\mathrm{cm}^{2}=1.0\\times 10^{-4}\\,\\mathrm{m}^{2}⟫","from":10}},{"id":"week14.3A.p20","kind":"num","q":"**[F10]** What force does a pressure of 25 kPa exert on an area of 0.030 m^2^?","marks":2,"level":2,"lines":2,"scheme":"⟪F=PA⟫ (1) ⟪=25\\,000\\times 0.030=750\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪F=PA⟫","marks":1},{"text":"⟪=25\\,000\\times 0.030=750\\,\\mathrm{N}⟫","marks":1}],"num":{"value":750,"sf":2,"unit":"N","unitTex":"\\mathrm{N}"},"section":"practice","hint":{"text":"Look back at Example 10 (F10 Pressure). Start like this: Convert: ⟪A=1.0\\,\\mathrm{cm}^{2}=1.0\\times 10^{-4}\\,\\mathrm{m}^{2}⟫","from":10}}],"exit":[{"id":"week14.3A.p21","kind":"num","q":"**[F11]** A diver is 25 m below the surface of seawater ⟪(\\rho =1030\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫. Find the pressure due to the water.","marks":2,"level":2,"lines":2,"scheme":"⟪P=\\rho gh=1030\\times 10\\times 25⟫ (1) ⟪=257\\,500\\,\\mathrm{Pa}\\approx 2.6\\times 10^{5}\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪P=\\rho gh=1030\\times 10\\times 25⟫","marks":1},{"text":"⟪=257\\,500\\,\\mathrm{Pa}\\approx 2.6\\times 10^{5}\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":260000,"sf":2,"unit":"Pa","unitTex":"\\mathrm{Pa}","alt":[257500]},"section":"exit"},{"id":"week14.3A.p22","kind":"self","q":"**[F11]** At what depth in fresh water is the water pressure 50 kPa?","marks":2,"level":2,"lines":2,"scheme":"⟪h=P\\div \\rho g⟫ (1) ⟪=50\\,000\\div (1000\\times 10)=5.0\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪h=P\\div \\rho g⟫","marks":1},{"text":"⟪=50\\,000\\div (1000\\times 10)=5.0\\,\\mathrm{m}⟫","marks":1}],"section":"exit"}],"warmup":[{"id":"week14.3A.w1","kind":"self","q":"During a thunderstorm you see the lightning before you hear the thunder. Explain why.","marks":2,"level":2,"lines":3,"scheme":"Both are produced at the same time (1), but light travels much faster ⟪(3\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫ than sound ⟪(\\approx 340\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫, so light arrives first (1).","points":[{"text":"Both are produced at the same time","marks":1},{"text":"but light travels much faster ⟪(3\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫ than sound ⟪(\\approx 340\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫, so light arrives first","marks":1}],"section":"warmup","src":"week14.2.p5"},{"id":"week14.3A.w2","kind":"self","q":"Explain why small gaps are left between sections of railway line.","marks":2,"level":2,"lines":3,"scheme":"Steel **expands** when heated on hot days (1); the gaps leave room for expansion so the rails do not **buckle** (1).","points":[{"text":"Steel **expands** when heated on hot days","marks":1},{"text":"the gaps leave room for expansion so the rails do not **buckle**","marks":1}],"section":"warmup","src":"week14.2.p3"},{"id":"week14.3A.w3","kind":"self","q":"Explain why soft iron, not steel, is used as the core of an electromagnet in an electric bell.","marks":2,"level":2,"lines":3,"scheme":"Soft iron is a **temporary** magnet — it is easily magnetised and **loses its magnetism** as soon as the current is switched off (1); steel would stay magnetised, so the bell's armature would not be released (1).","points":[{"text":"Soft iron is a **temporary** magnet — it is easily magnetised and **loses its magnetism** as soon as the current is switched off","marks":1},{"text":"steel would stay magnetised, so the bell's armature would not be released","marks":1}],"section":"warmup","src":"week14.2.p6"}],"n":103},{"id":"week14.3B","kind":"unit","unit":"3B","title":"Calculation Bank (2): Thermal Physics, Waves & Optics","titleText":"Calculation Bank (2): Thermal Physics, Waves & Optics","goals":[{"code":"B","text":"Section B — Thermal physics & kinetic theory: theories of heat, temperature & thermometers, phases, expansion, gas laws, specific heat & latent heat, heat transfer"},{"code":"C","text":"Section C — Waves & optics: wave motion, sound, EM spectrum, light (theories, reflection, refraction, TIR), lenses"}],"codes":["B","C"],"words":[],"learn":{"notes":[{"type":"p","text":"Section B formulas are mostly about energy (mcΔθ, ml) and gas laws (temperature in KELVIN!). Section C formulas are about waves, refraction and lenses."},{"type":"table","headers":["Code","Formula","Notes"],"rows":[["F12","⟪T(K)=\\theta ({}^{\\circ}\\mathrm{C})+273⟫;  ⟪p_{1}V_{1}/T_{1}=p_{2}V_{2}/T_{2}⟫  (Boyle: pV = constant)","T MUST be in kelvin; p and V in any matching units"],["F13","⟪E_{H}=mc\\Delta \\theta⟫;  for an electrical heater ⟪E=Pt\\ (=IVt)⟫","E in J; m in kg; c in J kg^−1^ °C^−1^ (water 4200); Δθ = temperature change in °C (or K)"],["F14","⟪E_{H}=ml⟫","l~f~ (ice) ⟪=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫; l~v~ (water) ⟪=2.3\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫. No temperature change"],["F15","heat lost by hot object = heat gained by cold object","⟪m_{1}c_{1}(\\theta _{1}-T)=m_{2}c_{2}(T-\\theta _{2})⟫, where T = final temperature"],["F16","⟪v=f\\lambda⟫;  ⟪T=1\\div f⟫","v in m s^−1^; f in Hz; λ in m; T (period) in s"],["F17","distance = (speed × time for echo) ÷ 2","Divide by 2 because the sound travels THERE AND BACK"],["F18","⟪n=\\sin i\\div \\sin r⟫;  ⟪n=c\\div v⟫ = (speed in vacuum/air) ÷ (speed in medium)","i = angle in the less dense medium (air); r = angle in the medium; n has no unit"],["F19","⟪\\sin c=1\\div n⟫","c = critical angle (angle in the denser medium when the refracted ray is at 90°). TIR when i > c"],["F20","⟪1/f=1/u+1/v⟫;  m = image height ÷ object height ⟪=v\\div u⟫","f = focal length; u = object distance; v = image distance (same units). Real is positive; a negative v means a virtual image"]]},{"type":"remember","text":"Every calculation: **Formula → Substitute (with units converted) → Answer with unit**, 2–3 s.f. Even if your final answer is wrong, the formula and substitution usually earn marks."},{"type":"tip","text":"Practise in this order: cover the worked example, try it yourself, check, then do the two practice questions marked with the same code (e.g. [F7])."}],"examples":[{"id":"week14.3B.e1","title":"F12 Pressure law","question":"A gas at ⟪2.0\\times 10^{5}\\,\\mathrm{Pa}⟫ and 27 °C is heated at constant volume to 127 °C. Find the new pressure.","steps":[{"label":"Kelvin","text":"⟪T_{1}=27+273=300\\,\\mathrm{K}⟫; ⟪T_{2}=127+273=400\\,\\mathrm{K}⟫"},{"label":"Formula","text":"⟪p_{1}/T_{1}=p_{2}/T_{2}⟫"},{"label":"Substitute","text":"⟪p_{2}=2.0\\times 10^{5}\\times 400\\div 300⟫"},{"label":"Calculate","text":"⟪p_{2}=2.7\\times 10^{5}\\,\\mathrm{Pa}\\ (2.67\\times 10^{5})⟫"}],"answer":"⟪2.7\\times 10^{5}\\,\\mathrm{Pa}⟫"},{"id":"week14.3B.e2","title":"F13 Heating water","question":"Find the energy needed to heat 2.0 kg of water from 25 °C to ⟪100\\,{}^{\\circ}\\mathrm{C}\\ (c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫.","steps":[{"label":"Δθ","text":"⟪100-25=75\\,{}^{\\circ}\\mathrm{C}⟫"},{"label":"Formula","text":"⟪E=mc\\Delta \\theta⟫"},{"label":"Substitute","text":"⟪E=2.0\\times 4200\\times 75⟫"},{"label":"Calculate","text":"⟪E=630\\,000\\,\\mathrm{J}=6.3\\times 10^{5}\\,\\mathrm{J}⟫"}],"answer":"⟪6.3\\times 10^{5}\\,\\mathrm{J}⟫"},{"id":"week14.3B.e3","title":"F14 Melting ice","question":"Find the energy needed to melt 0.20 kg of ice at ⟪0\\,{}^{\\circ}\\mathrm{C}\\ (l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫.","steps":[{"label":"Formula","text":"⟪E=ml⟫"},{"label":"Substitute","text":"⟪E=0.20\\times 3.4\\times 10^{5}⟫"},{"label":"Calculate","text":"⟪E=6.8\\times 10^{4}\\,\\mathrm{J}\\ (68\\,000\\,\\mathrm{J})⟫"}],"answer":"⟪6.8\\times 10^{4}\\,\\mathrm{J}⟫"},{"id":"week14.3B.e4","title":"F15 Mixing water","question":"0.20 kg of water at 80 °C is mixed with 0.30 kg of water at 20 °C. Find the final temperature T (no heat losses).","steps":[{"label":"Equation","text":"⟪0.20\\times 4200\\times (80-T)=0.30\\times 4200\\times (T-20)⟫"},{"label":"Cancel c","text":"⟪0.20(80-T)=0.30(T-20)\\rightarrow 16-0.20\\mathrm{T}=0.30\\mathrm{T}-6.0⟫"},{"label":"Solve","text":"⟪22=0.50\\mathrm{T}⟫"},{"label":"Calculate","text":"⟪T=44\\,{}^{\\circ}\\mathrm{C}⟫"}],"answer":"44 °C"},{"id":"week14.3B.e5","title":"F16 Radio wave","question":"A radio station broadcasts at 100 MHz. Find the wavelength ⟪(c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1})⟫.","steps":[{"label":"Convert","text":"⟪f=100\\,\\mathrm{MHz}=1.0\\times 10^{8}\\,\\mathrm{Hz}⟫"},{"label":"Formula","text":"⟪\\lambda =v\\div f⟫"},{"label":"Substitute","text":"⟪\\lambda =3.0\\times 10^{8}\\div 1.0\\times 10^{8}⟫"},{"label":"Calculate","text":"⟪\\lambda =3.0\\,\\mathrm{m}⟫"}],"answer":"3.0 m"},{"id":"week14.3B.e6","title":"F17 Echo from a cliff","question":"A girl claps and hears the echo from a cliff 0.60 s later. Speed of sound ⟪=330\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. How far away is the cliff?","steps":[{"label":"Total distance","text":"⟪d=vt=330\\times 0.60=198\\,\\mathrm{m}⟫ (there and back)"},{"label":"Halve","text":"⟪198\\div 2⟫"},{"label":"Calculate","text":"99 m"}],"answer":"99 m"},{"id":"week14.3B.e7","title":"F18 Snell's law","question":"A ray in air hits glass at ⟪i=40^{\\circ}⟫ and refracts at ⟪r=25^{\\circ}⟫. Find the refractive index of the glass.","steps":[{"label":"Formula","text":"⟪n=\\sin i\\div \\sin r⟫"},{"label":"Substitute","text":"⟪n=\\sin 40^{\\circ}\\div \\sin 25^{\\circ}=0.643\\div 0.423⟫"},{"label":"Calculate","text":"⟪n=1.52⟫"}],"answer":"1.52 (no unit)"},{"id":"week14.3B.e8","title":"F19 Critical angle","question":"Find the critical angle for glass of refractive index 1.50.","steps":[{"label":"Formula","text":"⟪\\sin c=1\\div n⟫"},{"label":"Substitute","text":"⟪\\sin c=1\\div 1.50=0.667⟫"},{"label":"Calculate","text":"⟪c=\\sin ^{-1}(0.667)=41.8^{\\circ}\\approx 42^{\\circ}⟫"}],"answer":"42°"},{"id":"week14.3B.e9","title":"F20 Converging lens","question":"An object is 30 cm from a converging lens of focal length 10 cm. Find the image position, magnification and nature.","steps":[{"label":"Formula","text":"⟪1/v=1/f-1/u⟫"},{"label":"Substitute","text":"⟪1/v=1/10-1/30=3/30-1/30=2/30⟫"},{"label":"v","text":"⟪v=15\\,\\mathrm{cm}⟫ (positive, so real, on the other side of the lens)"},{"label":"m","text":"⟪m=v\\div u=15\\div 30=0.50⟫"}],"answer":"⟪v=15\\,\\mathrm{cm}⟫; ⟪m=0.50⟫; real, inverted, diminished (like a camera)"}]},"tryit":[{"id":"week14.3B.p1","kind":"self","q":"**[F12]** Convert (a) −23 °C to kelvin (b) 373 K to °C.","marks":2,"level":2,"lines":2,"scheme":"(a) ⟪-23+273=250\\,\\mathrm{K}⟫ (1) (b) ⟪373-273=100\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"(a) ⟪-23+273=250\\,\\mathrm{K}⟫","marks":1},{"text":"(b) ⟪373-273=100\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"section":"try"},{"id":"week14.3B.p2","kind":"num","q":"**[F12]** 300 cm^3^ of gas at 100 kPa is squashed slowly (constant temperature) to 75 cm^3^. Find the new pressure.","marks":2,"level":2,"lines":3,"scheme":"⟪p_{1}V_{1}=p_{2}V_{2}⟫: ⟪100\\times 300=p_{2}\\times 75⟫ (1); ⟪p_{2}=400\\,\\mathrm{kPa}⟫ (1).","points":[{"text":"⟪p_{1}V_{1}=p_{2}V_{2}⟫: ⟪100\\times 300=p_{2}\\times 75⟫","marks":1},{"text":"⟪p_{2}=400\\,\\mathrm{kPa}⟫","marks":1}],"num":{"value":400,"sf":1,"unit":"kPa","unitTex":"\\mathrm{kPa}"},"section":"try","hint":{"text":"Look back at Example 1 (F12 Pressure law). Start like this: Kelvin: ⟪T_{1}=27+273=300\\,\\mathrm{K}⟫; ⟪T_{2}=127+273=400\\,\\mathrm{K}⟫","from":1}}],"practice":[{"id":"week14.3B.p3","kind":"num","q":"**[F13]** How much energy heats 0.50 kg of aluminium ⟪(c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫ from 20 °C to 60 °C?","marks":2,"level":2,"lines":2,"scheme":"⟪E=mc\\Delta \\theta =0.50\\times 900\\times 40⟫ (1) ⟪=18\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta =0.50\\times 900\\times 40⟫","marks":1},{"text":"⟪=18\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":18000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (F13 Heating water). Start like this: Δθ: ⟪100-25=75\\,{}^{\\circ}\\mathrm{C}⟫","from":2}},{"id":"week14.3B.p4","kind":"num","q":"**[F13]** A 2000 W kettle heats 1.5 kg of water from 30 °C to 100 °C. Assuming no heat losses, how long does it take?","marks":3,"level":2,"lines":3,"scheme":"⟪E=1.5\\times 4200\\times 70=441\\,000\\,\\mathrm{J}⟫ (1); ⟪t=E\\div P=441\\,000\\div 2000⟫ (1) ⟪=220.5\\,\\mathrm{s}\\approx 221\\,\\mathrm{s}⟫ (about 3.7 min) (1).","points":[{"text":"⟪E=1.5\\times 4200\\times 70=441\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"⟪t=E\\div P=441\\,000\\div 2000⟫","marks":1},{"text":"⟪=220.5\\,\\mathrm{s}\\approx 221\\,\\mathrm{s}⟫ (about 3.7 min)","marks":1}],"num":{"value":221,"sf":3,"unit":"s","unitTex":"\\mathrm{s}","alt":[220.5]},"conf":"low","section":"practice","hint":{"text":"Look back at Example 2 (F13 Heating water). Start like this: Δθ: ⟪100-25=75\\,{}^{\\circ}\\mathrm{C}⟫","from":2}},{"id":"week14.3B.p5","kind":"num","q":"**[F14]** How much energy is needed to turn 0.050 kg of boiling water into steam ⟪(l_{v}=2.3\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫?","marks":2,"level":2,"lines":2,"scheme":"⟪E=ml⟫ (1) ⟪=0.050\\times 2.3\\times 10^{6}=1.15\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=ml⟫","marks":1},{"text":"⟪=0.050\\times 2.3\\times 10^{6}=1.15\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":115000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (F13 Heating water). Start like this: Δθ: ⟪100-25=75\\,{}^{\\circ}\\mathrm{C}⟫","from":2}},{"id":"week14.3B.p6","kind":"num","q":"**[F14]** A 100 W heater melts 0.030 kg of ice in 102 s. Calculate the specific latent heat of fusion of ice.","marks":3,"level":2,"lines":3,"scheme":"⟪E=Pt=100\\times 102=10\\,200\\,\\mathrm{J}⟫ (1); ⟪l=E\\div m⟫ (1) ⟪=10\\,200\\div 0.030=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫ (1).","points":[{"text":"⟪E=Pt=100\\times 102=10\\,200\\,\\mathrm{J}⟫","marks":1},{"text":"⟪l=E\\div m⟫","marks":1},{"text":"⟪=10\\,200\\div 0.030=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫","marks":1}],"num":{"value":340000,"sf":2,"unit":"J kg^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}"},"section":"practice"},{"id":"week14.3B.p7","kind":"num","q":"**[F15]** 0.10 kg of water at 90 °C is mixed with 0.10 kg of water at 30 °C. Find the final temperature.","marks":2,"level":2,"lines":3,"scheme":"Equal masses, so heat lost = heat gained gives ⟪90-T=T-30⟫ (1); ⟪T=60\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"Equal masses, so heat lost = heat gained gives ⟪90-T=T-30⟫","marks":1},{"text":"⟪T=60\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"num":{"value":60,"sf":1,"unit":"°C","unitTex":"{}^{\\circ}\\mathrm{C}"},"section":"practice","hint":{"text":"Look back at Example 4 (F15 Mixing water). Start like this: Equation: ⟪0.20\\times 4200\\times (80-T)=0.30\\times 4200\\times (T-20)⟫","from":4}},{"id":"week14.3B.p8","kind":"num","q":"**[F15]** A 0.50 kg metal block at 100 °C is dropped into 0.40 kg of water at 20 °C. The final temperature is 28 °C. Find the specific heat capacity of the metal.","marks":3,"level":2,"lines":4,"scheme":"Heat gained by water ⟪=0.40\\times 4200\\times 8=13\\,440\\,\\mathrm{J}⟫ (1); heat lost by metal ⟪=0.50\\times c\\times 72⟫ (1); ⟪c=13\\,440\\div 36=373\\approx 370\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1).","points":[{"text":"Heat gained by water ⟪=0.40\\times 4200\\times 8=13\\,440\\,\\mathrm{J}⟫","marks":1},{"text":"heat lost by metal ⟪=0.50\\times c\\times 72⟫","marks":1},{"text":"⟪c=13\\,440\\div 36=373\\approx 370\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1}],"num":{"value":370,"sf":2,"unit":"J kg^−1^ °C^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}"},"conf":"low","section":"practice","hint":{"text":"Look back at Example 4 (F15 Mixing water). Start like this: Equation: ⟪0.20\\times 4200\\times (80-T)=0.30\\times 4200\\times (T-20)⟫","from":4}},{"id":"week14.3B.p9","kind":"self","q":"**[F16]** A wave has frequency 50 Hz and wavelength 0.40 m. Find its speed and its period.","marks":3,"level":2,"lines":3,"scheme":"⟪v=f\\lambda⟫ (1) ⟪=50\\times 0.40=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1); ⟪T=1\\div f=1\\div 50=0.020\\,\\mathrm{s}⟫ (1).","points":[{"text":"⟪v=f\\lambda⟫","marks":1},{"text":"⟪=50\\times 0.40=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1},{"text":"⟪T=1\\div f=1\\div 50=0.020\\,\\mathrm{s}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 5 (F16 Radio wave). Start like this: Convert: ⟪f=100\\,\\mathrm{MHz}=1.0\\times 10^{8}\\,\\mathrm{Hz}⟫","from":5}},{"id":"week14.3B.p10","kind":"num","q":"**[F16]** Sound travels at 340 m s^−1^. Find the frequency of a sound with a wavelength of 0.68 m.","marks":2,"level":2,"lines":2,"scheme":"⟪f=v\\div \\lambda⟫ (1) ⟪=340\\div 0.68=500\\,\\mathrm{Hz}⟫ (1).","points":[{"text":"⟪f=v\\div \\lambda⟫","marks":1},{"text":"⟪=340\\div 0.68=500\\,\\mathrm{Hz}⟫","marks":1}],"num":{"value":500,"sf":1,"unit":"Hz","unitTex":"\\mathrm{Hz}"},"section":"practice","hint":{"text":"Look back at Example 4 (F15 Mixing water). Start like this: Equation: ⟪0.20\\times 4200\\times (80-T)=0.30\\times 4200\\times (T-20)⟫","from":4}},{"id":"week14.3B.p11","kind":"self","q":"**[F17]** Thunder is heard 3.0 s after the lightning flash. Speed of sound ⟪=340\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫. How far away was the lightning? (No echo here!)","marks":2,"level":2,"lines":2,"scheme":"⟪d=vt⟫ (1) ⟪=340\\times 3.0=1020\\,\\mathrm{m}\\approx 1.0\\,\\mathrm{km}⟫ (1). (Not halved — the sound travels one way only.)","points":[{"text":"⟪d=vt⟫","marks":1},{"text":"⟪=340\\times 3.0=1020\\,\\mathrm{m}\\approx 1.0\\,\\mathrm{km}⟫ (Not halved — the sound travels one way only.)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 6 (F17 Echo from a cliff). Start like this: Total distance: ⟪d=vt=330\\times 0.60=198\\,\\mathrm{m}⟫ (there and back)","from":6}},{"id":"week14.3B.p12","kind":"num","q":"**[F17]** A ship's sonar pulse returns 0.40 s after it is sent. Sound travels at 1500 m s^−1^ in seawater. Find the depth of the sea.","marks":2,"level":2,"lines":3,"scheme":"⟪d=1500\\times 0.40=600\\,\\mathrm{m}⟫ there and back (1); depth ⟪=300\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪d=1500\\times 0.40=600\\,\\mathrm{m}⟫ there and back","marks":1},{"text":"depth ⟪=300\\,\\mathrm{m}⟫","marks":1}],"num":{"value":300,"sf":1,"unit":"m","unitTex":"\\mathrm{m}"},"section":"practice"},{"id":"week14.3B.p13","kind":"num","q":"**[F18]** Glass has ⟪n=1.5⟫. Find the speed of light in the glass.","marks":2,"level":2,"lines":2,"scheme":"⟪v=c\\div n⟫ (1) ⟪=3.0\\times 10^{8}\\div 1.5=2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"⟪v=c\\div n⟫","marks":1},{"text":"⟪=3.0\\times 10^{8}\\div 1.5=2.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":200000000,"sf":2,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"section":"practice","hint":{"text":"Look back at Example 7 (F18 Snell's law). Start like this: Formula: ⟪n=\\sin i\\div \\sin r⟫","from":7}},{"id":"week14.3B.p14","kind":"num","q":"**[F18]** A ray hits water ⟪(n=1.33)⟫ at ⟪i=30^{\\circ}⟫. Find the angle of refraction.","marks":3,"level":2,"lines":3,"scheme":"⟪\\sin r=\\sin 30^{\\circ}\\div 1.33⟫ (1) ⟪=0.500\\div 1.33=0.376⟫ (1); ⟪r=22^{\\circ}\\ (22.1^{\\circ})⟫ (1).","points":[{"text":"⟪\\sin r=\\sin 30^{\\circ}\\div 1.33⟫","marks":1},{"text":"⟪=0.500\\div 1.33=0.376⟫","marks":1},{"text":"⟪r=22^{\\circ}\\ (22.1^{\\circ})⟫","marks":1}],"num":{"value":22,"sf":2,"unit":"°","unitTex":"^{\\circ}","alt":[22.1]},"section":"practice","hint":{"text":"Look back at Example 2 (F13 Heating water). Start like this: Δθ: ⟪100-25=75\\,{}^{\\circ}\\mathrm{C}⟫","from":2}},{"id":"week14.3B.p15","kind":"num","q":"**[F19]** Diamond has a refractive index of 2.42. Find its critical angle.","marks":2,"level":2,"lines":2,"scheme":"⟪\\sin c=1\\div 2.42=0.413⟫ (1); ⟪c=24.4^{\\circ}⟫ (1).","points":[{"text":"⟪\\sin c=1\\div 2.42=0.413⟫","marks":1},{"text":"⟪c=24.4^{\\circ}⟫","marks":1}],"num":{"value":24.4,"sf":3,"unit":"°","unitTex":"^{\\circ}"},"section":"practice","hint":{"text":"Look back at Example 8 (F19 Critical angle). Start like this: Formula: ⟪\\sin c=1\\div n⟫","from":8}},{"id":"week14.3B.p16","kind":"num","q":"**[F19]** The critical angle of a liquid is 49°. Find its refractive index.","marks":2,"level":2,"lines":2,"scheme":"⟪n=1\\div \\sin 49^{\\circ}⟫ (1) ⟪=1\\div 0.755=1.33⟫ (1).","points":[{"text":"⟪n=1\\div \\sin 49^{\\circ}⟫","marks":1},{"text":"⟪=1\\div 0.755=1.33⟫","marks":1}],"num":{"value":1.33,"sf":3,"unit":"","unitTex":""},"section":"practice","hint":{"text":"Look back at Example 8 (F19 Critical angle). Start like this: Formula: ⟪\\sin c=1\\div n⟫","from":8}}],"exit":[{"id":"week14.3B.p17","kind":"self","q":"**[F20]** An object is 15 cm from a converging lens of focal length 10 cm. Find the image distance and magnification.","marks":3,"level":2,"lines":3,"scheme":"⟪1/v=1/10-1/15=1/30⟫ (1); ⟪v=30\\,\\mathrm{cm}⟫ (1); ⟪m=30\\div 15=2.0⟫ (real, inverted, magnified) (1).","points":[{"text":"⟪1/v=1/10-1/15=1/30⟫","marks":1},{"text":"⟪v=30\\,\\mathrm{cm}⟫","marks":1},{"text":"⟪m=30\\div 15=2.0⟫ (real, inverted, magnified)","marks":1}],"section":"exit"},{"id":"week14.3B.p18","kind":"self","q":"**[F20]** An object is 5.0 cm from a converging lens of focal length 10 cm. Find v and describe the image.","marks":3,"level":2,"lines":3,"scheme":"⟪1/v=1/10-1/5.0=-1/10⟫ (1); ⟪v=-10\\,\\mathrm{cm}⟫ (1); negative, so the image is virtual, upright and magnified ⟪(m=10\\div 5.0=2.0)⟫, on the same side as the object — a magnifying glass (1).","points":[{"text":"⟪1/v=1/10-1/5.0=-1/10⟫","marks":1},{"text":"⟪v=-10\\,\\mathrm{cm}⟫","marks":1},{"text":"negative, so the image is virtual, upright and magnified ⟪(m=10\\div 5.0=2.0)⟫, on the same side as the object — a magnifying glass","marks":1}],"section":"exit"}],"warmup":[{"id":"week14.3B.w1","kind":"num","q":"**[F1]** Cooking oil has a density of 0.80 g cm^−3^. Find the mass of 250 cm^3^ of oil.","marks":2,"level":2,"lines":2,"scheme":"⟪m=\\rho V⟫ (1) ⟪=0.80\\times 250=200\\,\\mathrm{g}\\ (0.20\\,\\mathrm{kg})⟫ (1).","points":[{"text":"⟪m=\\rho V⟫","marks":1},{"text":"⟪=0.80\\times 250=200\\,\\mathrm{g}\\ (0.20\\,\\mathrm{kg})⟫","marks":1}],"num":{"value":200,"sf":1,"unit":"g","unitTex":"\\mathrm{g}","alt":[0.2]},"section":"warmup","src":"week14.3A.p2"},{"id":"week14.3B.w2","kind":"num","q":"**[F1]** A stone of mass 60 g is lowered into a measuring cylinder. The water level rises from 40.0 cm^3^ to 64.0 cm^3^. Calculate the density of the stone.","marks":2,"level":2,"lines":3,"scheme":"⟪V=64.0-40.0=24.0\\,\\mathrm{cm}^{3}⟫ (1); ⟪\\rho =60\\div 24.0=2.5\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}\\ (2500\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫ (1).","points":[{"text":"⟪V=64.0-40.0=24.0\\,\\mathrm{cm}^{3}⟫","marks":1},{"text":"⟪\\rho =60\\div 24.0=2.5\\,\\mathrm{g}\\,\\mathrm{cm}^{-3}\\ (2500\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫","marks":1}],"num":{"value":2.5,"sf":2,"unit":"g cm^−3^","unitTex":"\\mathrm{g}\\,\\mathrm{cm}^{-3}","alt":[2500]},"section":"warmup","src":"week14.3A.p1"},{"id":"week14.3B.w3","kind":"num","q":"**[F2]** A 300 N child sits 2.0 m from the pivot of a see-saw. How far from the pivot, on the other side, must a 400 N child sit to balance?","marks":2,"level":2,"lines":3,"scheme":"⟪300\\times 2.0=400\\times d⟫ (1); ⟪d=600\\div 400=1.5\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪300\\times 2.0=400\\times d⟫","marks":1},{"text":"⟪d=600\\div 400=1.5\\,\\mathrm{m}⟫","marks":1}],"num":{"value":1.5,"sf":2,"unit":"m","unitTex":"\\mathrm{m}"},"section":"warmup","src":"week14.3A.p3"}],"n":104},{"id":"week14.3C","kind":"unit","unit":"3C","title":"Calculation Bank (3): Electricity & the Atom","titleText":"Calculation Bank (3): Electricity & the Atom","goals":[{"code":"D","text":"Section D — Electricity & magnetism: electrostatics, current, electrical quantities, circuits, mains, electronics, magnetism, electromagnetism & induction"},{"code":"E","text":"Section E — The physics of the atom: atomic models, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["D","E"],"words":[],"learn":{"notes":[{"type":"p","text":"Section D is the largest section of the syllabus, so expect at least one full electricity calculation on Paper 02. Section E calculations are short but easy marks: half-life, balancing equations and ⟪E=mc^{2}⟫."},{"type":"table","headers":["Code","Formula","Notes"],"rows":[["F21","⟪Q=It⟫;  ⟪Q=ne⟫","Q in C; I in A; t in s; ⟪e=1.6\\times 10^{-19}\\,\\mathrm{C}⟫ (charge on one electron)"],["F22","⟪V=IR⟫;  ⟪V=E\\div Q⟫","V in V; I in A; R in Ω; E = energy transferred (J); Q in C"],["F23","Series: ⟪R=R_{1}+R_{2}⟫ + …;  Parallel: ⟪1/R=1/R_{1}+1/R_{2}⟫ + …","Parallel total is always SMALLER than the smallest resistor. Series: same current; parallel: same p.d."],["F24","⟪P=IV⟫;  ⟪E=Pt⟫;  cost ⟪=\\mathrm{kWh}⟫ used × price per kWh","P in W (kW); E in J (P in W, t in s) or kWh (P in kW, t in h). ⟪1\\,\\mathrm{kWh}=3.6\\times 10^{6}\\,\\mathrm{J}⟫"],["F25","⟪I=P\\div V⟫, then choose the fuse rating just ABOVE this current","Common fuses: 3 A, 5 A, 13 A"],["F26","⟪V_{p}\\div V_{s}=N_{p}\\div N_{s}⟫;  ⟪V_{p}I_{p}=V_{s}I_{s}⟫ (ideal, 100 % efficient)","p = primary (input), s = secondary (output); N = number of turns"],["F27","⟪A=Z+N⟫;  in an equation the TOTAL A and the TOTAL Z are the same on both sides","A = nucleon (mass) number; Z = proton (atomic) number; N = neutrons. ⟪\\alpha ={}^{4}_{2}⟫He, ⟪\\beta ={}^{0}_{-1}e⟫"],["F28","After n half-lives: amount left = original ÷ 2^n^","Half-life = time for the activity (or number of undecayed nuclei) to fall to HALF"],["F29","⟪E=mc^{2}⟫","E in J; m = mass lost (mass defect) in kg; ⟪c=3.0\\times 10^{8}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}\\ (c^{2}=9.0\\times 10^{16})⟫"]]},{"type":"remember","text":"Every calculation: **Formula → Substitute (with units converted) → Answer with unit**, 2–3 s.f. Even if your final answer is wrong, the formula and substitution usually earn marks."},{"type":"tip","text":"Practise in this order: cover the worked example, try it yourself, check, then do the two practice questions marked with the same code (e.g. [F7])."}],"examples":[{"id":"week14.3C.e1","title":"F21 Charge","question":"A current of 0.50 A flows for 2.0 minutes. How much charge passes?","steps":[{"label":"Convert","text":"⟪t=2.0\\times 60=120\\,\\mathrm{s}⟫"},{"label":"Formula","text":"Q = It"},{"label":"Substitute","text":"⟪Q=0.50\\times 120⟫"},{"label":"Calculate","text":"⟪Q=60\\,\\mathrm{C}⟫"}],"answer":"60 C"},{"id":"week14.3C.e2","title":"F22 Resistance of a lamp","question":"A lamp takes 0.50 A from a 12 V supply. Find its resistance.","steps":[{"label":"Formula","text":"⟪R=V\\div I⟫"},{"label":"Substitute","text":"⟪R=12\\div 0.50⟫"},{"label":"Calculate","text":"⟪R=24\\,\\Omega⟫"}],"answer":"24 Ω"},{"id":"week14.3C.e3","title":"F23 Combination","question":"A 20 Ω and a 30 Ω resistor are in parallel, and this pair is in series with an 8.0 Ω resistor across a 10 V supply. Find the total resistance and the supply current.","steps":[{"label":"Parallel","text":"⟪1/R=1/20+1/30=3/60+2/60=5/60\\rightarrow R=12\\,\\Omega⟫"},{"label":"Series","text":"⟪R_{\\text{total}}=12+8.0=20\\,\\Omega⟫"},{"label":"Current","text":"⟪I=V\\div R=10\\div 20⟫"},{"label":"Calculate","text":"⟪I=0.50\\,\\mathrm{A}⟫"}],"answer":"20 Ω; 0.50 A"},{"id":"week14.3C.e4","title":"F24 Cost of ironing","question":"A 1500 W iron is used for 2.0 hours a day for 30 days. Electricity costs $0.90 per kWh. Find the cost.","steps":[{"label":"Convert","text":"⟪P=1500\\,\\mathrm{W}=1.5\\,\\mathrm{kW}⟫; ⟪t=2.0\\times 30=60\\,\\mathrm{h}⟫"},{"label":"Energy","text":"⟪E=Pt=1.5\\times 60=90\\,\\mathrm{kWh}⟫"},{"label":"Cost","text":"⟪90\\times \\$0.90⟫"},{"label":"Calculate","text":"$81.00"}],"answer":"$81.00"},{"id":"week14.3C.e5","title":"F25 Fuse for a hair dryer","question":"A 2000 W hair dryer runs on 240 V. Which fuse — 3 A, 5 A or 13 A — should be fitted?","steps":[{"label":"Formula","text":"⟪I=P\\div V⟫"},{"label":"Substitute","text":"⟪I=2000\\div 240=8.3\\,\\mathrm{A}⟫"},{"label":"Choose","text":"the next rating ABOVE 8.3 A"}],"answer":"13 A (a 5 A fuse would blow in normal use; 3 A even more so)"},{"id":"week14.3C.e6","title":"F26 Step-down transformer","question":"A transformer changes 240 V to 12 V. The primary coil has 2000 turns. How many turns are on the secondary?","steps":[{"label":"Formula","text":"⟪N_{s}=N_{p}\\times V_{s}\\div V_{p}⟫"},{"label":"Substitute","text":"⟪N_{s}=2000\\times 12\\div 240⟫"},{"label":"Calculate","text":"⟪N_{s}=100⟫ turns"}],"answer":"100 turns"},{"id":"week14.3C.e7","title":"F27 Alpha decay","question":"Uranium-⟪238\\ (Z=92)⟫ decays by emitting an alpha particle to thorium (Th). Write the equation and find the number of neutrons in U-238.","steps":[{"label":"Neutrons","text":"⟪N=A-Z=238-92=146⟫"},{"label":"Alpha","text":"α has ⟪A=4⟫, ⟪Z=2⟫"},{"label":"Balance","text":"A: ⟪238=234+4⟫; Z: ⟪92=90+2⟫"},{"label":"Equation","text":"⟪{}^{238}_{92}U\\rightarrow {}^{234}_{90}Th+{}^{4}_{2}⟫He"}],"answer":"⟪{}^{238}_{92}U\\rightarrow {}^{234}_{90}Th+{}^{4}_{2}⟫He; 146 neutrons"},{"id":"week14.3C.e8","title":"F28 Half-life","question":"A source has an activity of 800 Bq and a half-life of 6.0 hours. Find its activity after 24 hours.","steps":[{"label":"Half-lives","text":"⟪n=24\\div 6.0=4⟫"},{"label":"Halve 4 times","text":"800 → 400 → 200 → 100 → 50"},{"label":"Calculate","text":"50 Bq"}],"answer":"50 Bq"},{"id":"week14.3C.e9","title":"F29 Mass defect","question":"In one nuclear reaction the mass lost is ⟪3.0\\times 10^{-29}\\,\\mathrm{kg}⟫. How much energy is released?","steps":[{"label":"Formula","text":"⟪E=mc^{2}⟫"},{"label":"Substitute","text":"⟪E=3.0\\times 10^{-29}\\times (3.0\\times 10^{8})^{2}=3.0\\times 10^{-29}\\times 9.0\\times 10^{16}⟫"},{"label":"Calculate","text":"⟪E=2.7\\times 10^{-12}\\,\\mathrm{J}⟫"}],"answer":"⟪2.7\\times 10^{-12}\\,\\mathrm{J}⟫"}]},"tryit":[{"id":"week14.3C.p1","kind":"num","q":"**[F21]** How long does it take for 900 C to pass when the current is 2.5 A?","marks":2,"level":2,"lines":2,"scheme":"⟪t=Q\\div I⟫ (1) ⟪=900\\div 2.5=360\\,\\mathrm{s}\\ (6.0\\,\\mathrm{min})⟫ (1).","points":[{"text":"⟪t=Q\\div I⟫","marks":1},{"text":"⟪=900\\div 2.5=360\\,\\mathrm{s}\\ (6.0\\,\\mathrm{min})⟫","marks":1}],"num":{"value":360,"sf":2,"unit":"s","unitTex":"\\mathrm{s}","alt":[6]},"section":"try"},{"id":"week14.3C.p2","kind":"self","q":"**[F21]** A current of 3.2 A flows. How many electrons pass a point each second?","marks":3,"level":2,"lines":3,"scheme":"Q in ⟪1\\,\\mathrm{s}=3.2\\,\\mathrm{C}⟫ (1); ⟪n=Q\\div e=3.2\\div 1.6\\times 10^{-19}⟫ (1) ⟪=2.0\\times 10^{19}⟫ electrons (1).","points":[{"text":"Q in ⟪1\\,\\mathrm{s}=3.2\\,\\mathrm{C}⟫","marks":1},{"text":"⟪n=Q\\div e=3.2\\div 1.6\\times 10^{-19}⟫","marks":1},{"text":"⟪=2.0\\times 10^{19}⟫ electrons","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (F21 Charge). Start like this: Convert: ⟪t=2.0\\times 60=120\\,\\mathrm{s}⟫","from":1}}],"practice":[{"id":"week14.3C.p3","kind":"num","q":"**[F22]** Find the current in a 15 Ω resistor with 6.0 V across it.","marks":2,"level":2,"lines":2,"scheme":"⟪I=V\\div R⟫ (1) ⟪=6.0\\div 15=0.40\\,\\mathrm{A}⟫ (1).","points":[{"text":"⟪I=V\\div R⟫","marks":1},{"text":"⟪=6.0\\div 15=0.40\\,\\mathrm{A}⟫","marks":1}],"num":{"value":0.4,"sf":2,"unit":"A","unitTex":"\\mathrm{A}"},"section":"practice","hint":{"text":"Look back at Example 3 (F23 Combination). Start like this: Parallel: ⟪1/R=1/20+1/30=3/60+2/60=5/60\\rightarrow R=12\\,\\Omega⟫","from":3}},{"id":"week14.3C.p4","kind":"num","q":"**[F22]** How much energy does a 9.0 V battery transfer when 20 C of charge flows through it?","marks":2,"level":2,"lines":2,"scheme":"⟪E=VQ⟫ (1) ⟪=9.0\\times 20=180\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=VQ⟫","marks":1},{"text":"⟪=9.0\\times 20=180\\,\\mathrm{J}⟫","marks":1}],"num":{"value":180,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (F21 Charge). Start like this: Convert: ⟪t=2.0\\times 60=120\\,\\mathrm{s}⟫","from":1}},{"id":"week14.3C.p5","kind":"self","q":"**[F23]** Three 4.0 Ω resistors are connected (a) in series (b) in parallel. Find the total resistance each time.","marks":2,"level":2,"lines":3,"scheme":"(a) ⟪4.0+4.0+4.0=12\\,\\Omega⟫ (1). (b) ⟪1/R=3/4.0\\rightarrow R=1.3\\,\\Omega \\ (1.33\\,\\Omega )⟫ (1).","points":[{"text":"(a) ⟪4.0+4.0+4.0=12\\,\\Omega⟫","marks":1},{"text":"(b) ⟪1/R=3/4.0\\rightarrow R=1.3\\,\\Omega \\ (1.33\\,\\Omega )⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (F23 Combination). Start like this: Parallel: ⟪1/R=1/20+1/30=3/60+2/60=5/60\\rightarrow R=12\\,\\Omega⟫","from":3}},{"id":"week14.3C.p6","kind":"self","q":"**[F23]** Two 10 Ω resistors in parallel are connected to a 6.0 V battery. Find the total current and the current in each resistor.","marks":3,"level":2,"lines":3,"scheme":"⟪R=5.0\\,\\Omega⟫ (1); ⟪I=6.0\\div 5.0=1.2\\,\\mathrm{A}⟫ (1); 0.60 A in each (equal resistors share equally) (1).","points":[{"text":"⟪R=5.0\\,\\Omega⟫","marks":1},{"text":"⟪I=6.0\\div 5.0=1.2\\,\\mathrm{A}⟫","marks":1},{"text":"0.60 A in each (equal resistors share equally)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (F23 Combination). Start like this: Parallel: ⟪1/R=1/20+1/30=3/60+2/60=5/60\\rightarrow R=12\\,\\Omega⟫","from":3}},{"id":"week14.3C.p7","kind":"num","q":"**[F24]** A lamp takes 0.25 A from a 240 V supply. Find its power.","marks":2,"level":2,"lines":2,"scheme":"⟪P=IV⟫ (1) ⟪=0.25\\times 240=60\\,\\mathrm{W}⟫ (1).","points":[{"text":"⟪P=IV⟫","marks":1},{"text":"⟪=0.25\\times 240=60\\,\\mathrm{W}⟫","marks":1}],"num":{"value":60,"sf":1,"unit":"W","unitTex":"\\mathrm{W}"},"section":"practice","hint":{"text":"Look back at Example 2 (F22 Resistance of a lamp). Start like this: Formula: ⟪R=V\\div I⟫","from":2}},{"id":"week14.3C.p8","kind":"self","q":"**[F24]** A 2.0 kW heater is used for 3.0 hours. Find the energy used in kWh and in joules.","marks":3,"level":2,"lines":3,"scheme":"⟪E=2.0\\times 3.0=6.0\\,\\mathrm{kWh}⟫ (1); × ⟪3.6\\times 10^{6}⟫ (1) ⟪=2.16\\times 10^{7}\\,\\mathrm{J}\\approx 2.2\\times 10^{7}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=2.0\\times 3.0=6.0\\,\\mathrm{kWh}⟫","marks":1},{"text":"× ⟪3.6\\times 10^{6}⟫","marks":1},{"text":"⟪=2.16\\times 10^{7}\\,\\mathrm{J}\\approx 2.2\\times 10^{7}\\,\\mathrm{J}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (F24 Cost of ironing). Start like this: Convert: ⟪P=1500\\,\\mathrm{W}=1.5\\,\\mathrm{kW}⟫; ⟪t=2.0\\times 30=60\\,\\mathrm{h}⟫","from":4}},{"id":"week14.3C.p9","kind":"self","q":"**[F25]** A 1200 W microwave runs on a 110 V supply. Calculate the current and choose a fuse from 3 A, 5 A, 13 A.","marks":2,"level":2,"lines":2,"scheme":"⟪I=1200\\div 110=10.9\\,\\mathrm{A}⟫ (1); 13 A fuse (1).","points":[{"text":"⟪I=1200\\div 110=10.9\\,\\mathrm{A}⟫","marks":1},{"text":"13 A fuse","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (F22 Resistance of a lamp). Start like this: Formula: ⟪R=V\\div I⟫","from":2}},{"id":"week14.3C.p10","kind":"self","q":"**[F25]** Which fuse (3 A, 5 A, 13 A) should be used for a 60 W lamp on 240 V? Explain why a 13 A fuse would be dangerous.","marks":3,"level":2,"lines":3,"scheme":"⟪I=60\\div 240=0.25\\,\\mathrm{A}⟫ (1); 3 A fuse (1); a 13 A fuse would let a large fault current flow without melting, so the flex could overheat and cause a fire (1).","points":[{"text":"⟪I=60\\div 240=0.25\\,\\mathrm{A}⟫","marks":1},{"text":"3 A fuse","marks":1},{"text":"a 13 A fuse would let a large fault current flow without melting, so the flex could overheat and cause a fire","marks":1}],"section":"practice","hint":{"text":"Look back at Example 5 (F25 Fuse for a hair dryer). Start like this: Formula: ⟪I=P\\div V⟫","from":5}},{"id":"week14.3C.p11","kind":"self","q":"**[F26]** A transformer has 500 primary turns and 2500 secondary turns. The input is 120 V. Find the output voltage and say whether it is step-up or step-down.","marks":2,"level":2,"lines":2,"scheme":"⟪V_{s}=120\\times 2500\\div 500=600\\,\\mathrm{V}⟫ (1); step-up (1).","points":[{"text":"⟪V_{s}=120\\times 2500\\div 500=600\\,\\mathrm{V}⟫","marks":1},{"text":"step-up","marks":1}],"section":"practice","hint":{"text":"Look back at Example 6 (F26 Step-down transformer). Start like this: Formula: ⟪N_{s}=N_{p}\\times V_{s}\\div V_{p}⟫","from":6}},{"id":"week14.3C.p12","kind":"num","q":"**[F26]** An ideal transformer steps 240 V down to 12 V. The secondary current is 2.0 A. Find the primary current.","marks":2,"level":2,"lines":3,"scheme":"⟪V_{p}I_{p}=V_{s}I_{s}⟫: ⟪240\\times I_{p}=12\\times 2.0⟫ (1); ⟪I_{p}=0.10\\,\\mathrm{A}⟫ (1).","points":[{"text":"⟪V_{p}I_{p}=V_{s}I_{s}⟫: ⟪240\\times I_{p}=12\\times 2.0⟫","marks":1},{"text":"⟪I_{p}=0.10\\,\\mathrm{A}⟫","marks":1}],"num":{"value":0.1,"sf":2,"unit":"A","unitTex":"\\mathrm{A}"},"section":"practice","hint":{"text":"Look back at Example 6 (F26 Step-down transformer). Start like this: Formula: ⟪N_{s}=N_{p}\\times V_{s}\\div V_{p}⟫","from":6}},{"id":"week14.3C.p13","kind":"num","q":"**[F27]** Carbon-14 has ⟪Z=6⟫. How many neutrons are in its nucleus?","marks":1,"level":1,"lines":1,"scheme":"⟪N=14-6=8⟫ (1).","points":[{"text":"⟪N=14-6=8⟫","marks":1}],"num":{"value":8,"sf":1,"unit":"","unitTex":""},"section":"practice","hint":{"text":"Look back at Example 6 (F26 Step-down transformer). Start like this: Formula: ⟪N_{s}=N_{p}\\times V_{s}\\div V_{p}⟫","from":6}},{"id":"week14.3C.p14","kind":"self","q":"**[F27]** Strontium-⟪90\\ (Z=38)⟫ decays by beta emission to yttrium (Y). Write the balanced equation.","marks":3,"level":2,"lines":3,"scheme":"⟪{}^{90}_{38}Sr\\rightarrow {}^{90}_{39}Y+{}^{0}_{-1}e⟫: A stays 90 (1); Z rises by 1 to 39 (1); beta particle written correctly (1).","points":[{"text":"⟪{}^{90}_{38}Sr\\rightarrow {}^{90}_{39}Y+{}^{0}_{-1}e⟫: A stays 90","marks":1},{"text":"Z rises by 1 to 39","marks":1},{"text":"beta particle written correctly","marks":1}],"section":"practice","hint":{"text":"Look back at Example 7 (F27 Alpha decay). Start like this: Neutrons: ⟪N=A-Z=238-92=146⟫","from":7}},{"id":"week14.3C.p15","kind":"self","q":"**[F28]** What fraction of a radioactive sample is left after 3 half-lives?","marks":1,"level":1,"lines":1,"scheme":"⟪\\tfrac{1}{2}\\times \\tfrac{1}{2}\\times \\tfrac{1}{2}=1/8⟫ (1).","points":[{"text":"⟪\\tfrac{1}{2}\\times \\tfrac{1}{2}\\times \\tfrac{1}{2}=1/8⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 8 (F28 Half-life). Start like this: Half-lives: ⟪n=24\\div 6.0=4⟫","from":8}},{"id":"week14.3C.p16","kind":"num","q":"**[F28]** The count rate of a sample falls from 1600 to 200 counts per minute in 15 days. Find the half-life.","marks":3,"level":2,"lines":3,"scheme":"1600 → 800 → 400 → 200 is 3 half-lives (1)(1); half-life ⟪=15\\div 3=5.0\\,\\mathrm{days}⟫ (1).","points":[{"text":"1600 → 800 → 400 → 200 is 3 half-lives","marks":2},{"text":"half-life ⟪=15\\div 3=5.0\\,\\mathrm{days}⟫","marks":1}],"num":{"value":5,"sf":2,"unit":"days","unitTex":"\\mathrm{days}"},"section":"practice","hint":{"text":"Look back at Example 8 (F28 Half-life). Start like this: Half-lives: ⟪n=24\\div 6.0=4⟫","from":8}}],"exit":[{"id":"week14.3C.p17","kind":"num","q":"**[F29]** How much energy would be released if 1.0 g of mass were converted completely into energy?","marks":2,"level":2,"lines":2,"scheme":"⟪m=1.0\\times 10^{-3}\\,\\mathrm{kg}⟫ (1); ⟪E=1.0\\times 10^{-3}\\times 9.0\\times 10^{16}=9.0\\times 10^{13}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪m=1.0\\times 10^{-3}\\,\\mathrm{kg}⟫","marks":1},{"text":"⟪E=1.0\\times 10^{-3}\\times 9.0\\times 10^{16}=9.0\\times 10^{13}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":90000000000000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"exit"},{"id":"week14.3C.p18","kind":"num","q":"**[F29]** A reaction releases ⟪1.8\\times 10^{-11}\\,\\mathrm{J}⟫. Find the mass lost.","marks":2,"level":2,"lines":2,"scheme":"⟪m=E\\div c^{2}⟫ (1) ⟪=1.8\\times 10^{-11}\\div 9.0\\times 10^{16}=2.0\\times 10^{-28}\\,\\mathrm{kg}⟫ (1).","points":[{"text":"⟪m=E\\div c^{2}⟫","marks":1},{"text":"⟪=1.8\\times 10^{-11}\\div 9.0\\times 10^{16}=2.0\\times 10^{-28}\\,\\mathrm{kg}⟫","marks":1}],"num":{"value":2e-28,"sf":2,"unit":"kg","unitTex":"\\mathrm{kg}"},"section":"exit"}],"warmup":[{"id":"week14.3C.w1","kind":"num","q":"**[F14]** How much energy is needed to turn 0.050 kg of boiling water into steam ⟪(l_{v}=2.3\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫?","marks":2,"level":2,"lines":2,"scheme":"⟪E=ml⟫ (1) ⟪=0.050\\times 2.3\\times 10^{6}=1.15\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=ml⟫","marks":1},{"text":"⟪=0.050\\times 2.3\\times 10^{6}=1.15\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":115000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week14.3B.p5"},{"id":"week14.3C.w2","kind":"num","q":"**[F12]** 300 cm^3^ of gas at 100 kPa is squashed slowly (constant temperature) to 75 cm^3^. Find the new pressure.","marks":2,"level":2,"lines":3,"scheme":"⟪p_{1}V_{1}=p_{2}V_{2}⟫: ⟪100\\times 300=p_{2}\\times 75⟫ (1); ⟪p_{2}=400\\,\\mathrm{kPa}⟫ (1).","points":[{"text":"⟪p_{1}V_{1}=p_{2}V_{2}⟫: ⟪100\\times 300=p_{2}\\times 75⟫","marks":1},{"text":"⟪p_{2}=400\\,\\mathrm{kPa}⟫","marks":1}],"num":{"value":400,"sf":1,"unit":"kPa","unitTex":"\\mathrm{kPa}"},"section":"warmup","src":"week14.3B.p2"},{"id":"week14.3C.w3","kind":"num","q":"**[F13]** How much energy heats 0.50 kg of aluminium ⟪(c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫ from 20 °C to 60 °C?","marks":2,"level":2,"lines":2,"scheme":"⟪E=mc\\Delta \\theta =0.50\\times 900\\times 40⟫ (1) ⟪=18\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta =0.50\\times 900\\times 40⟫","marks":1},{"text":"⟪=18\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":18000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week14.3B.p3"}],"n":105},{"id":"week14.4","kind":"unit","unit":"4","title":"Final Checklist & Exam-Day Strategy","titleText":"Final Checklist & Exam-Day Strategy","goals":[{"code":"A","text":"Section A — Mechanics: scientific method & graphs, measurement, vectors, statics (moments, Hooke), dynamics (Newton, momentum), energy & power, hydrostatics"},{"code":"B","text":"Section B — Thermal physics & kinetic theory: theories of heat, temperature & thermometers, phases, expansion, gas laws, specific heat & latent heat, heat transfer"},{"code":"C","text":"Section C — Waves & optics: wave motion, sound, EM spectrum, light (theories, reflection, refraction, TIR), lenses"},{"code":"D","text":"Section D — Electricity & magnetism: electrostatics, current, electrical quantities, circuits, mains, electronics, magnetism, electromagnetism & induction"},{"code":"E","text":"Section E — The physics of the atom: atomic models, atomic structure, radioactivity, half-life, nuclear energy"}],"codes":["A","B","C","D","E"],"words":[{"term":"Best-fit line","def":"One straight ruled line (or smooth curve) passing as close as possible to all the points, with points evenly spread on both sides."},{"term":"Gradient","def":"Steepness of a line ⟪=\\Delta y\\div \\Delta x⟫, found with a large triangle; its unit is unit y ÷ unit x."}],"learn":{"notes":[{"type":"h","text":"1. Know the paper before you sit it"},{"type":"table","headers":["Paper","Date","Time","What is in it","Marks"],"rows":[["Paper 02","Tue 5 Jan 2027","2 h 30 min","Section A: Q1 data analysis ⟪(25)+Q2⟫, Q3 structured (15 each). Section B: Q4, Q5, Q6 extended response (15 each). ALL compulsory.","100"],["Paper 01","Mon 25 Jan 2027","1 h 15 min","60 multiple-choice questions on all sections","60"]]},{"type":"p","text":"The questions can come from **any** section. As a rough guide, Electricity & Magnetism (D) carries the most marks, then Mechanics (A), Waves & Optics (C), Thermal Physics (B), and the Atom (E) the fewest — but every section appears, so there is no 'safe' topic to skip."},{"type":"h","text":"2. Timing: about 1½ minutes per mark"},{"type":"img","src":"img/week14/timeline","alt":"Figure 4.1 — A time plan for Paper 02 (150 minutes)","caption":"Figure 4.1 — A time plan for Paper 02 (150 minutes)","width":6,"w":1367,"h":354},{"type":"table","headers":["Question","Marks","Time budget","Clock check (if starting at 9:00)"],"rows":[["Read the whole paper, plan","—","5 min","9:05"],["Q1 Data analysis","25","40 min","9:45"],["Q2","15","20 min","10:05"],["Q3","15","20 min","10:25"],["Q4","15","20 min","10:45"],["Q5","15","20 min","11:05"],["Q6","15","20 min","11:25"],["Check answers & units","—","5 min","11:30"]]},{"type":"warn","text":"Spending an hour on Question 1 because the graph is 'nearly perfect'. When the time budget runs out, **move on**. Come back at the end if there is time."},{"type":"h","text":"3. Order of attack"},{"type":"steps","items":["**Read every question** quickly (5 min). Mark each one ✓ (I can do this), ? (partly), ✗ (hard).","**Do Question 1 first** — you have drilled the graph skills; it is 25 marks; you need a fresh, steady hand for the plotting.","Next do the ✓ questions, then the ? questions, then the ✗ questions. Number every answer clearly so the examiner can find it.","In every question, grab the **easy marks first**: definitions, 'state' parts, formula + substitution.","Never leave a blank. A formula, a labelled diagram or one correct point can still score.","Last 5 minutes: check every number has a **unit**, every graph has **labels**, and you answered **the right number of points**."]},{"type":"tip","text":"**Error carried forward (ECF):** if you get part (a) wrong but use your wrong answer correctly in part (b), you still get the marks for (b). So ALWAYS finish the later parts — never give up because an early part went wrong."},{"type":"h","text":"4. Equipment checklist (pack the night before)"},{"type":"table","headers":["Item","Why","Packed ✓"],"rows":[["2 black/blue pens","Answers",""],["2 sharp HB pencils + sharpener + eraser","Graphs and diagrams MUST be in pencil",""],["30 cm clear ruler","Ruled best-fit lines, gradient triangles, ray diagrams",""],["Scientific calculator (fresh battery, in DEG mode)","sin/sin^−1^ for refraction; standard form",""],["Protractor and geometry set","Angles of incidence/refraction, vectors",""],["Exam slip / ID, watch (non-smart)","Entry and timing",""]]},{"type":"warn","text":"Calculator in **RAD** mode instead of **DEG**. Check now: sin 30 must give 0.5."},{"type":"h","text":"5. Topic checklist — tick each one you can do without notes"},{"type":"table","headers":["Section","I can… (tick)","✓"],"rows":[["A","Plot a graph and find a gradient; Galileo/Aristotle points; scalar vs vector; resultant of 2 vectors; moments; Hooke's law; Newton's 3 laws; v–t graphs (gradient & area); momentum; PE/KE; power; efficiency; pressure; Archimedes",""],["B","Caloric vs kinetic theory, Joule; thermometers; kinetic theory of solids/liquids/gases; expansion; gas laws + kelvin; mcΔθ; ml; heating/cooling curves; evaporation vs boiling; conduction, convection, radiation; vacuum flask",""],["C","Transverse vs longitudinal; ⟪v=f\\lambda⟫; displacement graphs; sound & echoes; EM spectrum order + uses; Newton vs Huygens, Young; reflection; refraction & Snell's law; critical angle & TIR; lenses: ray diagrams, ⟪1/f=1/u+1/v⟫",""],["D","Static charge & induction; uses/hazards of static; Q = It; a.c. vs d.c.; ⟪V=IR⟫; series/parallel; cells; I–V graphs; ⟪P=IV⟫, kWh, cost; fuses, earthing, house wiring; rectification; logic gates; magnetism & fields; electromagnets; motor effect & Fleming's LH rule; d.c. motor; induction; generator; transformer",""],["E","Atomic models (Dalton → Chadwick); Geiger–Marsden; ⟪A=Z+N⟫; isotopes; α, β, γ properties; nuclear equations; half-life graphs & calculations; uses of radioisotopes; ⟪E=mc^{2}⟫; nuclear energy for/against",""]]},{"type":"h","text":"6. The last week (29 Dec – 4 Jan)"},{"type":"table","headers":["Day","Do this","Time"],"rows":[["Tue 29 Dec","Unit 1 data sets 1–⟪2+PP1⟫ timed (40 min)","1 h 15"],["Wed 30 Dec","Unit 2: say E1–E20 aloud; do Unit 2 practice","1 h"],["Thu 31 Dec","Calculation bank ⟪3\\mathrm{A}+3B⟫ (cover the worked examples first)","1 h 15"],["Fri 1 Jan","Rest morning; Calculation bank 3C; formula card from memory","1 h"],["Sat 2 Jan","S1–S4 TIMED (20 min each); mark with the key","1 h 30"],["Sun 3 Jan","PP2 timed; Mistake Log review; topic checklist","1 h 15"],["Mon 4 Jan","LIGHT: formula card, model answers E1–E20, pack bag, sleep early","45 min"]]},{"type":"remember","text":"Sleep matters more than one extra hour of cramming. Eat breakfast, arrive 30 minutes early, and bring water."}],"examples":[{"id":"week14.4.e1","title":"Planning your time on one question","question":"A 15-mark question has parts (a) 2 marks, (b) 4 marks, (c) 3 marks, (d) 6 marks. How long should you spend on each part?","steps":[{"label":"Rule","text":"about 1½ minutes per mark (⟪150\\,\\mathrm{min}\\div 100⟫ marks)"},{"label":"(a)","text":"⟪2\\times 1.5=3\\,\\mathrm{min}⟫"},{"label":"(b)","text":"⟪4\\times 1.5=6\\,\\mathrm{min}⟫"},{"label":"(c)","text":"⟪3\\times 1.5=4.5\\,\\mathrm{min}⟫"},{"label":"(d)","text":"⟪6\\times 1.5=9\\,\\mathrm{min}⟫"}],"answer":"⟪3+6+4.5+9=22.5\\,\\mathrm{min}⟫ — slightly over the 20-minute budget, so be brief on (a) and (c)."},{"id":"week14.4.e2","title":"Rescuing a calculation you are stuck on (ECF)","question":"Part (a) asks for the total resistance of a circuit and you are not sure of your answer (you get 5 Ω). Part (b) asks for the current from a 12 V supply. What should you do?","steps":[{"label":"Don't stop","text":"Write your best answer to (a): ⟪R=5\\,\\Omega⟫."},{"label":"Use it","text":"(b) ⟪I=V\\div R=12\\div 5=2.4\\,\\mathrm{A}⟫"},{"label":"Why","text":"If (a) is wrong, (b) can still score full marks by error carried forward, because the method is right."}],"answer":"Always carry on with your own earlier answer; write the formula and substitution so the examiner can award ECF."}]},"tryit":[{"id":"week14.4.p1","kind":"self","q":"Your exam starts at 9:00 a.m. Using the time plan, at what time should you be finishing Question 3? What should you do if you have not finished Q1 by 9:45?","marks":2,"level":2,"lines":3,"scheme":"10:25 a.m. (1); leave Q1 (note which part to return to), move on to Q2 and come back to Q1 at the end (1).","points":[{"text":"10:25 a.m.","marks":1},{"text":"leave Q1 (note which part to return to), move on to Q2 and come back to Q1 at the end","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Planning your time on one question). Start like this: Rule: about 1½ minutes per mark (⟪150\\,\\mathrm{min}\\div 100⟫ marks)","from":1}},{"id":"week14.4.p2","kind":"self","q":"Paper 02 has 100 marks in 150 minutes. Show that this is about 1½ minutes per mark, and find how long to spend on a 25-mark question.","marks":2,"level":2,"lines":2,"scheme":"⟪150\\div 100=1.5\\,\\mathrm{min}⟫ per mark (1); ⟪25\\times 1.5=37.5\\approx 40\\,\\mathrm{min}⟫ (1).","points":[{"text":"⟪150\\div 100=1.5\\,\\mathrm{min}⟫ per mark","marks":1},{"text":"⟪25\\times 1.5=37.5\\approx 40\\,\\mathrm{min}⟫","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Planning your time on one question). Start like this: Rule: about 1½ minutes per mark (⟪150\\,\\mathrm{min}\\div 100⟫ marks)","from":1}}],"practice":[{"id":"week14.4.p3","kind":"self","q":"List SIX things you will check in the last 5 minutes of Paper 02.","marks":3,"level":2,"lines":4,"scheme":"Any six, ½ each (3): every numerical answer has a unit; answers to 2–3 s.f.; graph axes labelled with units; best-fit line ruled; every question/part attempted; number of points matches the marks; question numbers written clearly; calculator in DEG mode for any sin values; diagrams labelled.","points":[{"text":"Any six, ½ each. : every numerical answer has a unit; answers to 2–3 s.f.; graph axes labelled with units; best-fit line ruled; every question/part attempted; number of points matches the marks; question numbers written clearly; calculator in DEG mode for any sin values; diagrams labelled","marks":3}],"section":"practice"},{"id":"week14.4.p4","kind":"self","q":"Rate yourself on the topic checklist (Section 5). Write down your THREE weakest topics and, for each, the unit or page in this book you will use to revise it.","marks":3,"level":2,"lines":4,"scheme":"Personal answer (tutor to check): three specific topics (e.g. 'transformer equations', 'lens ray diagrams', 'half-life graphs') each matched to a unit/page (1 mark each).","points":[{"text":"Personal answer (tutor to check): three specific topics (e.g. 'transformer equations', 'lens ray diagrams', 'half-life graphs') each matched to a unit/page (1 mark each).","marks":3,"each":true}],"section":"practice"}],"exit":[{"id":"week14.4.p5","kind":"self","q":"Explain what 'error carried forward' means and why you should never leave the later parts of a question blank.","marks":2,"level":2,"lines":3,"scheme":"If an early answer is wrong but you use it correctly in a later part, you can still get the marks for the later part (1); so attempting later parts with your own answer can still score full marks for method (1).","points":[{"text":"If an early answer is wrong but you use it correctly in a later part, you can still get the marks for the later part","marks":1},{"text":"so attempting later parts with your own answer can still score full marks for method","marks":1}],"section":"exit"},{"id":"week14.4.p6","kind":"self","q":"Write out the master formula card (end of this book) from memory. Then check it and count how many you got completely right.","marks":4,"level":3,"lines":6,"scheme":"Self-marked against the Formula & Fact Card. Target: at least 25 correct. Tutor: re-test any missed formulas at the start of the session.","points":[{"text":"Self-marked against the Formula & Fact Card. Target: at least 25 correct. Tutor: re-test any missed formulas at the start of the session.","marks":4}],"conf":"low","section":"exit"}],"warmup":[{"id":"week14.4.w1","kind":"self","q":"**[F28]** What fraction of a radioactive sample is left after 3 half-lives?","marks":1,"level":1,"lines":1,"scheme":"⟪\\tfrac{1}{2}\\times \\tfrac{1}{2}\\times \\tfrac{1}{2}=1/8⟫ (1).","points":[{"text":"⟪\\tfrac{1}{2}\\times \\tfrac{1}{2}\\times \\tfrac{1}{2}=1/8⟫","marks":1}],"section":"warmup","src":"week14.3C.p15"},{"id":"week14.4.w2","kind":"num","q":"**[F27]** Carbon-14 has ⟪Z=6⟫. How many neutrons are in its nucleus?","marks":1,"level":1,"lines":1,"scheme":"⟪N=14-6=8⟫ (1).","points":[{"text":"⟪N=14-6=8⟫","marks":1}],"num":{"value":8,"sf":1,"unit":"","unitTex":""},"section":"warmup","src":"week14.3C.p13"}],"n":106},{"id":"week14.check","kind":"check","title":"Book check","titleText":"Book check","check":true,"watchOut":["Plotting the graph the wrong way round — in 'plot y against x', the FIRST quantity goes on the y-axis.","Using an awkward scale (3, 6, 7 or 9 per square) or drawing a tiny graph that uses less than half the grid.","Joining the points dot-to-dot instead of drawing ONE ruled best-fit line (or a smooth curve).","Using a small gradient triangle, or data points far off the line, and forgetting the unit of the gradient.","Leaving temperature in °C in the gas laws — it MUST be in kelvin ⟪(\\theta +273)⟫.","Forgetting to convert units before substituting: g → kg, cm → m, cm^2^ → m^2^, minutes → s, kW → W (or use kW and hours for kWh).","Forgetting to divide by 2 in echo questions — or wrongly dividing by 2 for thunder (one-way).","Not subtracting the background count before finding a half-life.","Writing one vague sentence for a 4-mark 'explain'. Count the marks and give that many separate points, using the key words.","Calculator in RAD mode, so every sin value is wrong. Check: ⟪\\sin 30=0.5⟫."],"mcq":[],"structured":[{"id":"week14.check.s1","kind":"multi","title":"Section A — Motion, force and energy","total":15,"stem":["The velocity–time graph shows the motion of a car of mass 1200 kg along a straight road."],"stemBlocks":[{"type":"img","src":"img/week14/s1_vt","alt":"Velocity–time graph of the car","caption":"Velocity–time graph of the car","width":4.8,"w":1172,"h":694}],"parts":[{"id":"week14.check.s1.a","kind":"self","q":"Calculate the acceleration of the car between O and A.","marks":2,"level":2,"lines":2,"scheme":"⟪a=(v-u)\\div t=(20-0)\\div 8⟫ (1) ⟪=2.5\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (1).","points":[{"text":"⟪a=(v-u)\\div t=(20-0)\\div 8⟫","marks":1},{"text":"⟪=2.5\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫","marks":1}],"label":"(a)"},{"id":"week14.check.s1.b","kind":"self","q":"Calculate the resultant force on the car between O and A.","marks":2,"level":2,"lines":2,"scheme":"⟪F=ma=1200\\times 2.5⟫ (1) ⟪=3000\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪F=ma=1200\\times 2.5⟫","marks":1},{"text":"⟪=3000\\,\\mathrm{N}⟫","marks":1}],"label":"(b)"},{"id":"week14.check.s1.c","kind":"self","q":"Calculate the total distance travelled by the car in the 25 s.","marks":3,"level":2,"lines":3,"scheme":"Distance = area under the graph (1) ⟪=\\tfrac{1}{2}\\times 8\\times 20+12\\times 20+\\tfrac{1}{2}\\times 5\\times 20=80+240+50⟫ (1) ⟪=370\\,\\mathrm{m}⟫ (1).","points":[{"text":"Distance = area under the graph","marks":1},{"text":"⟪=\\tfrac{1}{2}\\times 8\\times 20+12\\times 20+\\tfrac{1}{2}\\times 5\\times 20=80+240+50⟫","marks":1},{"text":"⟪=370\\,\\mathrm{m}⟫","marks":1}],"num":{"value":370,"sf":2,"unit":"m","unitTex":"\\mathrm{m}"},"label":"(c)","autoKind":"num"},{"id":"week14.check.s1.d","kind":"self","q":"Calculate the kinetic energy of the car between A and B.","marks":2,"level":2,"lines":2,"scheme":"⟪E_{k}=\\tfrac{1}{2}mv^{2}=\\tfrac{1}{2}\\times 1200\\times 20^{2}⟫ (1) ⟪=240\\,000\\,\\mathrm{J}=2.4\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E_{k}=\\tfrac{1}{2}mv^{2}=\\tfrac{1}{2}\\times 1200\\times 20^{2}⟫","marks":1},{"text":"⟪=240\\,000\\,\\mathrm{J}=2.4\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"label":"(d)"},{"id":"week14.check.s1.e","kind":"self","q":"Between B and C the car brakes. Calculate the braking force.","marks":2,"level":2,"lines":3,"scheme":"⟪a=20\\div 5=4.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (deceleration) (1); ⟪F=ma=1200\\times 4.0=4800\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪a=20\\div 5=4.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (deceleration)","marks":1},{"text":"⟪F=ma=1200\\times 4.0=4800\\,\\mathrm{N}⟫","marks":1}],"num":{"value":4800,"sf":2,"unit":"N","unitTex":"\\mathrm{N}"},"label":"(e)","autoKind":"num"},{"id":"week14.check.s1.f","kind":"self","q":"Define linear momentum and calculate the momentum of the car between A and B.","marks":2,"level":2,"lines":2,"scheme":"Momentum = mass × velocity (1); ⟪p=1200\\times 20=24\\,000\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"Momentum = mass × velocity","marks":1},{"text":"⟪p=1200\\times 20=24\\,000\\,\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"label":"(f)"},{"id":"week14.check.s1.g","kind":"self","q":"Use Newton's first law to explain why passengers should wear seatbelts while the car brakes from B to C.","marks":2,"level":2,"lines":3,"scheme":"Passengers have inertia and continue to move forward at 20 m s^−1^ when the car slows (1); the seatbelt provides the (backward) force needed to decelerate them with the car (1).","points":[{"text":"Passengers have inertia and continue to move forward at 20 m s^−1^ when the car slows","marks":1},{"text":"the seatbelt provides the (backward) force needed to decelerate them with the car","marks":1}],"label":"(g)"}]},{"id":"week14.check.s2","kind":"multi","title":"Section B — Heating ice to steam","total":15,"stem":["A 500 W immersion heater is placed in 0.50 kg of crushed ice, initially at −20 °C. The graph shows how the temperature changes. Assume all the heater's energy goes into the ice/water."],"stemBlocks":[{"type":"img","src":"img/week14/s2_heating","alt":"Temperature–time graph (heating curve)","caption":"Temperature–time graph (heating curve)","width":5,"w":1214,"h":734}],"parts":[{"id":"week14.check.s2.a","kind":"self","q":"State the physical state(s) of the water in section QR and in section RS.","marks":2,"level":2,"lines":2,"scheme":"QR: solid and liquid (melting) (1); RS: liquid (1).","points":[{"text":"QR: solid and liquid (melting)","marks":1},{"text":"RS: liquid","marks":1}],"label":"(a)"},{"id":"week14.check.s2.b","kind":"self","q":"Explain, in terms of molecules, why the temperature does not change between Q and R although the heater is on.","marks":3,"level":2,"lines":4,"scheme":"Energy supplied is latent heat (1); it breaks/weakens the bonds between molecules (increases PE) (1); KE of the molecules does not increase, so temperature stays at 0 °C (1).","points":[{"text":"Energy supplied is latent heat","marks":1},{"text":"it breaks/weakens the bonds between molecules (increases PE)","marks":1},{"text":"KE of the molecules does not increase, so temperature stays at 0 °C","marks":1}],"label":"(b)"},{"id":"week14.check.s2.c","kind":"self","q":"Use the graph to find how long the ice takes to melt, and calculate the energy supplied in that time.","marks":2,"level":2,"lines":3,"scheme":"⟪t=382-42=340\\,\\mathrm{s}⟫ (1); ⟪E=Pt=500\\times 340=170\\,000\\,\\mathrm{J}=1.7\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪t=382-42=340\\,\\mathrm{s}⟫","marks":1},{"text":"⟪E=Pt=500\\times 340=170\\,000\\,\\mathrm{J}=1.7\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"label":"(c)"},{"id":"week14.check.s2.d","kind":"self","q":"Calculate the specific latent heat of fusion of ice.","marks":2,"level":2,"lines":2,"scheme":"⟪l=E\\div m⟫ (1) ⟪=170\\,000\\div 0.50=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫ (1).","points":[{"text":"⟪l=E\\div m⟫","marks":1},{"text":"⟪=170\\,000\\div 0.50=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫","marks":1}],"num":{"value":340000,"sf":2,"unit":"J kg^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}"},"label":"(d)","autoKind":"num"},{"id":"week14.check.s2.e","kind":"self","q":"Use section RS to calculate the specific heat capacity of water.","marks":3,"level":2,"lines":4,"scheme":"Time ⟪=802-382=420\\,\\mathrm{s}⟫, so ⟪E=500\\times 420=210\\,000\\,\\mathrm{J}⟫ (1); ⟪c=E\\div (m\\Delta \\theta )=210\\,000\\div (0.50\\times 100)⟫ (1) ⟪=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1).","points":[{"text":"Time ⟪=802-382=420\\,\\mathrm{s}⟫, so ⟪E=500\\times 420=210\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"⟪c=E\\div (m\\Delta \\theta )=210\\,000\\div (0.50\\times 100)⟫","marks":1},{"text":"⟪=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1}],"num":{"value":4200,"sf":2,"unit":"J kg^−1^ °C^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}"},"label":"(e)","autoKind":"num"},{"id":"week14.check.s2.f","kind":"self","q":"In a real experiment heat is gained from the room while the ice melts. State the effect on the value of l obtained and give ONE precaution to reduce this error.","marks":2,"level":2,"lines":3,"scheme":"The heater supplies less energy than needed for melting, so the calculated l is too LOW (1); insulate/lag the container (or use a control funnel of ice with no heater and subtract its melt) (1).","points":[{"text":"The heater supplies less energy than needed for melting, so the calculated l is too LOW","marks":1},{"text":"insulate/lag the container (or use a control funnel of ice with no heater and subtract its melt)","marks":1}],"label":"(f)"},{"id":"week14.check.s2.g","kind":"self","q":"State ONE difference between boiling (section ST) and evaporation.","marks":1,"level":1,"lines":2,"scheme":"Boiling occurs at a fixed temperature (100 °C) / throughout the liquid; evaporation occurs at any temperature / only at the surface (1).","points":[{"text":"Boiling occurs at a fixed temperature (100 °C) / throughout the liquid; evaporation occurs at any temperature / only at the surface","marks":1}],"label":"(g)"}]},{"id":"week14.check.s3","kind":"multi","title":"Section C — Water waves, lenses and light","total":15,"stem":["A ripple tank produces water waves of frequency 5.0 Hz. The graph shows the displacement of the water surface at one instant."],"stemBlocks":[{"type":"img","src":"img/week14/s3_wave","alt":"Displacement–distance graph of the water wave","caption":"Displacement–distance graph of the water wave","width":5,"w":1214,"h":574}],"parts":[{"id":"week14.check.s3.a","kind":"self","q":"Use the graph to find (i) the amplitude (ii) the wavelength of the wave.","marks":2,"level":2,"lines":2,"scheme":"(i) 1.5 cm (1) (ii) 4.0 cm (1).","points":[{"text":"(i) 1.5 cm","marks":1},{"text":"(ii) 4.0 cm","marks":1}],"label":"(a)"},{"id":"week14.check.s3.b","kind":"self","q":"Calculate the speed of the wave in m s^−1^.","marks":2,"level":2,"lines":2,"scheme":"⟪v=f\\lambda =5.0\\times 0.040⟫ (1) ⟪=0.20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"⟪v=f\\lambda =5.0\\times 0.040⟫","marks":1},{"text":"⟪=0.20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":0.2,"sf":2,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"label":"(b)","autoKind":"num"},{"id":"week14.check.s3.c","kind":"self","q":"Calculate the period of the wave.","marks":1,"level":1,"lines":1,"scheme":"⟪T=1\\div f=1\\div 5.0=0.20\\,\\mathrm{s}⟫ (1).","points":[{"text":"⟪T=1\\div f=1\\div 5.0=0.20\\,\\mathrm{s}⟫","marks":1}],"num":{"value":0.2,"sf":2,"unit":"s","unitTex":"\\mathrm{s}"},"label":"(c)","autoKind":"num"},{"id":"week14.check.s3.d","kind":"self","q":"The waves pass into shallower water where their speed is 0.12 m s^−1^. State what happens to the frequency and calculate the new wavelength.","marks":2,"level":2,"lines":3,"scheme":"Frequency stays the same, 5.0 Hz (1); ⟪\\lambda =v\\div f=0.12\\div 5.0=0.024\\,\\mathrm{m}=2.4\\,\\mathrm{cm}⟫ (1).","points":[{"text":"Frequency stays the same, 5.0 Hz","marks":1},{"text":"⟪\\lambda =v\\div f=0.12\\div 5.0=0.024\\,\\mathrm{m}=2.4\\,\\mathrm{cm}⟫","marks":1}],"label":"(d)"},{"id":"week14.check.s3.e","kind":"self","q":"Water waves are transverse. Explain what this means.","marks":2,"level":2,"lines":2,"scheme":"The particles (water surface) vibrate perpendicular to (1) the direction in which the wave travels / energy is transferred (1).","points":[{"text":"The particles (water surface) vibrate perpendicular to","marks":1},{"text":"the direction in which the wave travels / energy is transferred","marks":1}],"label":"(e)"},{"id":"week14.check.s3.f","kind":"self","q":"An object is placed 15 cm from a converging lens of focal length 10 cm. Calculate the image distance and the magnification, and state TWO properties of the image.","marks":4,"level":3,"lines":5,"scheme":"⟪1/v=1/10-1/15=1/30⟫ (1); ⟪v=30\\,\\mathrm{cm}⟫ (1); ⟪m=v/u=30/15=2.0⟫ (1); real AND inverted (or magnified) — any two (1).","points":[{"text":"⟪1/v=1/10-1/15=1/30⟫","marks":1},{"text":"⟪v=30\\,\\mathrm{cm}⟫","marks":1},{"text":"⟪m=v/u=30/15=2.0⟫","marks":1},{"text":"real AND inverted (or magnified) — any two","marks":1}],"label":"(f)"},{"id":"week14.check.s3.g","kind":"self","q":"The lens is made of glass of refractive index 1.50. Calculate the critical angle of the glass.","marks":2,"level":2,"lines":2,"scheme":"⟪\\sin c=1/n=1/1.50=0.667⟫ (1); ⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫ (1).","points":[{"text":"⟪\\sin c=1/n=1/1.50=0.667⟫","marks":1},{"text":"⟪c=41.8^{\\circ}\\approx 42^{\\circ}⟫","marks":1}],"num":{"value":42,"sf":2,"unit":"°","unitTex":"^{\\circ}","alt":[41.8]},"label":"(g)","autoKind":"num"}]},{"id":"week14.check.s4","kind":"multi","title":"Section D — Circuits and the home","total":15,"stem":["The circuit shows a 12 V battery connected to three resistors. The battery and ammeter have negligible resistance."],"stemBlocks":[{"type":"img","src":"img/week14/s4_circuit","alt":"Series–parallel circuit","caption":"Series–parallel circuit","width":4.4,"w":1042,"h":654}],"parts":[{"id":"week14.check.s4.a","kind":"self","q":"Calculate the combined resistance of R~2~ and R~3~, and the total resistance of the circuit.","marks":3,"level":2,"lines":3,"scheme":"⟪1/R=1/6.0+1/3.0=3/6.0⟫ (1); ⟪R=2.0\\,\\Omega⟫ (1); total ⟪=4.0+2.0=6.0\\,\\Omega⟫ (1).","points":[{"text":"⟪1/R=1/6.0+1/3.0=3/6.0⟫","marks":1},{"text":"⟪R=2.0\\,\\Omega⟫","marks":1},{"text":"total ⟪=4.0+2.0=6.0\\,\\Omega⟫","marks":1}],"label":"(a)"},{"id":"week14.check.s4.b","kind":"self","q":"Calculate the reading on the ammeter.","marks":2,"level":2,"lines":2,"scheme":"⟪I=V\\div R=12\\div 6.0⟫ (1) ⟪=2.0\\,\\mathrm{A}⟫ (1).","points":[{"text":"⟪I=V\\div R=12\\div 6.0⟫","marks":1},{"text":"⟪=2.0\\,\\mathrm{A}⟫","marks":1}],"num":{"value":2,"sf":2,"unit":"A","unitTex":"\\mathrm{A}"},"label":"(b)","autoKind":"num"},{"id":"week14.check.s4.c","kind":"self","q":"Calculate (i) the p.d. across R~1~ (ii) the p.d. across R~3~ (iii) the current in R~3~.","marks":3,"level":2,"lines":4,"scheme":"(i) ⟪V=IR=2.0\\times 4.0=8.0\\,\\mathrm{V}⟫ (1). (ii) ⟪12-8.0=4.0\\,\\mathrm{V}⟫ (1). (iii) ⟪I=4.0\\div 3.0=1.3\\,\\mathrm{A}\\ (1.33\\,\\mathrm{A})⟫ (1).","points":[{"text":"(i) ⟪V=IR=2.0\\times 4.0=8.0\\,\\mathrm{V}⟫","marks":1},{"text":"(ii) ⟪12-8.0=4.0\\,\\mathrm{V}⟫","marks":1},{"text":"(iii) ⟪I=4.0\\div 3.0=1.3\\,\\mathrm{A}\\ (1.33\\,\\mathrm{A})⟫","marks":1}],"label":"(c)"},{"id":"week14.check.s4.d","kind":"self","q":"Calculate the power dissipated in R~1~.","marks":1,"level":1,"lines":2,"scheme":"⟪P=I^{2}R⟫ (or IV) = 2.0^2^ × 4.0 = 16 W (1).","points":[{"text":"⟪P=I^{2}R⟫ (or IV) = 2.0^2^ × 4.0 = 16 W","marks":1}],"num":{"value":16,"sf":2,"unit":"W","unitTex":"\\mathrm{W}"},"label":"(d)","autoKind":"num"},{"id":"week14.check.s4.e","kind":"self","q":"A kettle is rated 2.4 kW, 240 V. Calculate its working current and choose a suitable fuse from 3 A, 5 A and 13 A.","marks":2,"level":2,"lines":2,"scheme":"⟪I=P\\div V=2400\\div 240=10\\,\\mathrm{A}⟫ (1); 13 A fuse (1).","points":[{"text":"⟪I=P\\div V=2400\\div 240=10\\,\\mathrm{A}⟫","marks":1},{"text":"13 A fuse","marks":1}],"label":"(e)"},{"id":"week14.check.s4.f","kind":"self","q":"The kettle is used for 15 minutes a day for 30 days. Electricity costs $0.80 per kWh. Calculate the cost.","marks":2,"level":2,"lines":3,"scheme":"⟪E=2.4\\,\\mathrm{kW}\\times 0.25\\,\\mathrm{h}\\times 30=18\\,\\mathrm{kWh}⟫ (1); cost ⟪=18\\times \\$0.80=\\$14.40⟫ (1).","points":[{"text":"⟪E=2.4\\,\\mathrm{kW}\\times 0.25\\,\\mathrm{h}\\times 30=18\\,\\mathrm{kWh}⟫","marks":1},{"text":"cost ⟪=18\\times \\$0.80=\\$14.40⟫","marks":1}],"num":{"value":14.4,"sf":4,"unit":"","unitTex":""},"label":"(f)","autoKind":"num"},{"id":"week14.check.s4.g","kind":"self","q":"The kettle has a metal case. Explain why it must be earthed.","marks":2,"level":2,"lines":3,"scheme":"If the live wire touches the case, current flows to earth through the low-resistance earth wire instead of through a person (1); the large current blows the fuse, cutting off the supply so the case is not live (1).","points":[{"text":"If the live wire touches the case, current flows to earth through the low-resistance earth wire instead of through a person","marks":1},{"text":"the large current blows the fuse, cutting off the supply so the case is not live","marks":1}],"label":"(g)"}]}],"n":107},{"id":"week14.past","kind":"past","title":"Past-paper practice","titleText":"Past-paper practice","check":true,"log":true,"questions":[{"id":"week14.past.q1","kind":"multi","title":"Paper 02 Question 1 style — Radioactive decay (Section E)","total":25,"stem":["A student used a Geiger–Müller (GM) tube and counter to measure the count rate from a radioactive source every minute. Before bringing the source in, she measured the background count rate as 20 counts per minute.","Her results are shown in the table."],"stemBlocks":[{"type":"table","headers":["Time, t / min","0","1","2","3","4","5","6","7","8"],"rows":[["Measured count rate / counts min^−1^","660","475","338","248","182","131","102","75","61"],["Corrected count rate / counts min^−1^","640","455","","228","","111","82","","41"]]}],"parts":[{"id":"week14.past.q1.a","kind":"self","q":"Explain what is meant by 'background count' and name TWO sources of background radiation.","marks":3,"level":2,"lines":3,"scheme":"Radiation detected when no source is present (1); any two: rocks/soil (radon gas), cosmic rays, medical/X-rays, food, building materials, nuclear fallout (1)(1).","points":[{"text":"Radiation detected when no source is present","marks":1},{"text":"any two: rocks/soil (radon gas), cosmic rays, medical/X-rays, food, building materials, nuclear fallout","marks":2}],"label":"(a)"},{"id":"week14.past.q1.b","kind":"self","q":"Complete the table by calculating the corrected count rate for ⟪t=2⟫, 4 and 7 min.","marks":3,"level":2,"lines":2,"scheme":"318 (1); 162 (1); 55 (1) [measured − 20].","points":[{"text":"318","marks":1},{"text":"162","marks":1},{"text":"55. [measured − 20]","marks":1}],"label":"(b)"},{"id":"week14.past.q1.c","kind":"self","q":"Plot a graph of corrected count rate (y-axis) against time (x-axis). Draw a smooth curve of best fit.","marks":7,"level":3,"img":{"src":"img/week14/grid","alt":"Plot a graph of corrected count rate (y-axis) against time (x-axis). Draw a smooth curve of best fit.","w":1254,"h":974},"lines":0,"scheme":"Axes labelled 'Time, t / min' and 'Corrected count rate / counts min^−1^' (1); scale using more than half the grid, e.g. x: 0.5 min per big square (16 squares), y: 100 counts min^−1^ per big square (6.4 of 12 squares) (1); all nine points correct (3, −1 per error); smooth curve of best fit, NOT dot-to-dot (1); title (1).","points":[{"text":"Axes labelled 'Time, t / min' and 'Corrected count rate / counts min^−1^'","marks":1},{"text":"scale using more than half the grid, e.g. x: 0.5 min per big square (16 squares), y: 100 counts min^−1^ per big square (6.4 of 12 squares)","marks":1},{"text":"all nine points correct (3, −1 per error); smooth curve of best fit, NOT dot-to-dot","marks":1},{"text":"title","marks":1}],"conf":"low","label":"(c)"},{"id":"week14.past.q1.d","kind":"self","q":"Use your graph to determine the half-life of the source. Show TWO separate halvings on your graph and take the average.","marks":4,"level":3,"lines":4,"scheme":"Construction lines shown on the graph (1); e.g. 640 → 320 takes ≈ 2.0 min (1); 320 → 160 takes ≈ 2.0 min (1); half-life ⟪=2.0\\,\\mathrm{min}⟫ (accept 1.8–2.2 min) (1).","points":[{"text":"Construction lines shown on the graph","marks":1},{"text":"e.g. 640 → 320 takes ≈ 2.0 min","marks":1},{"text":"320 → 160 takes ≈ 2.0 min","marks":1},{"text":"half-life ⟪=2.0\\,\\mathrm{min}⟫ (accept 1.8–2.2 min)","marks":1}],"num":{"value":2,"sf":2,"unit":"min","unitTex":"\\mathrm{min}","min":1.8,"max":2.2},"conf":"low","label":"(d)","autoKind":"num"},{"id":"week14.past.q1.e","kind":"self","q":"The points do not lie exactly on a smooth curve. Explain why.","marks":2,"level":2,"lines":2,"scheme":"Radioactive decay is random (1), so the count in any one minute fluctuates about the average (1).","points":[{"text":"Radioactive decay is random","marks":1},{"text":"so the count in any one minute fluctuates about the average","marks":1}],"label":"(e)"},{"id":"week14.past.q1.f","kind":"self","q":"Predict the MEASURED count rate (including background) after 10 min.","marks":3,"level":2,"lines":3,"scheme":"⟪10\\,\\mathrm{min}=5⟫ half-lives (1); corrected ⟪=640\\div 2^{5}=20⟫ counts min^−1^ (1); measured ⟪=20+20=40⟫ counts min^−1^ (1).","points":[{"text":"⟪10\\,\\mathrm{min}=5⟫ half-lives","marks":1},{"text":"corrected ⟪=640\\div 2^{5}=20⟫ counts min^−1^","marks":1},{"text":"measured ⟪=20+20=40⟫ counts min^−1^","marks":1}],"label":"(f)"},{"id":"week14.past.q1.g","kind":"self","q":"State ONE way to make the readings more reliable and ONE safety precaution when handling the source.","marks":2,"level":2,"lines":2,"scheme":"Reliability: count for longer (e.g. several minutes) and average / repeat readings / keep the source–tube distance fixed (1). Safety: handle with tongs / keep source pointing away from body / return to lead box immediately / minimise time of exposure (1).","points":[{"text":"Reliability: count for longer (e.g. several minutes) and average / repeat readings / keep the source–tube distance fixed","marks":1},{"text":"Safety: handle with tongs / keep source pointing away from body / return to lead box immediately / minimise time of exposure","marks":1}],"label":"(g)"},{"id":"week14.past.q1.h","kind":"self","q":"State the dependent and the controlled variables in this experiment.","marks":1,"level":1,"lines":2,"scheme":"Dependent: count rate; controlled: distance between source and GM tube (or same tube/counter, same orientation) — both needed for (1).","points":[{"text":"Dependent: count rate; controlled: distance between source and GM tube (or same tube/counter, same orientation) — both needed for","marks":1}],"label":"(h)"}]},{"id":"week14.past.q2","kind":"multi","title":"Paper 02 Question 1 style — Energy on an air track (Section A)","total":25,"stem":["A student released a glider from rest at different heights, h, on a sloping air track (almost no friction). A light gate at the bottom measured its speed, v. Her results are shown below."],"stemBlocks":[{"type":"table","headers":["Height, h / m","0.050","0.100","0.150","0.200","0.250","0.300"],"rows":[["Speed, v / m s^−1^","0.98","1.41","1.70","1.99","2.20","2.43"],["v^2^ / m^2^ s^−2^","0.96","","2.89","","4.84","5.90"]]}],"parts":[{"id":"week14.past.q2.a","kind":"self","q":"Complete the table by calculating v^2^ for ⟪h=0.100\\,\\mathrm{m}⟫ and h = 0.200 m (2 decimal places).","marks":2,"level":2,"lines":2,"scheme":"⟪1.41^{2}=1.99⟫ (1); ⟪1.99^{2}=3.96⟫ (1).","points":[{"text":"⟪1.41^{2}=1.99⟫","marks":1},{"text":"⟪1.99^{2}=3.96⟫","marks":1}],"label":"(a)"},{"id":"week14.past.q2.b","kind":"self","q":"Name the independent and dependent variables, and state ONE variable that must be controlled.","marks":3,"level":2,"lines":3,"scheme":"Independent: height h (1); dependent: speed v (or v^2^) (1); controlled: mass of glider / same glider / same track and light gate / release from rest (1).","points":[{"text":"Independent: height h","marks":1},{"text":"dependent: speed v (or v^2^)","marks":1},{"text":"controlled: mass of glider / same glider / same track and light gate / release from rest","marks":1}],"label":"(b)"},{"id":"week14.past.q2.c","kind":"self","q":"Plot a graph of v^2^ (y-axis) against h (x-axis) on the grid. Draw the line of best fit.","marks":7,"level":3,"img":{"src":"img/week14/grid","alt":"Plot a graph of v2 (y-axis) against h (x-axis) on the grid. Draw the line of best fit.","w":1254,"h":974},"lines":0,"scheme":"Axes labelled 'v^2^ / m^2^ s^−2^' and 'h / m' (1); sensible scale using more than half the grid, e.g. x: 0.02 m per big square (15 squares), y: 0.5 m^2^ s^−2^ per big square (11.8 squares) (2); all six points correct (2, −1 per error); straight ruled line through (close to) the origin (1); title (1).","points":[{"text":"Axes labelled 'v^2^ / m^2^ s^−2^' and 'h / m'","marks":1},{"text":"sensible scale using more than half the grid, e.g. x: 0.02 m per big square (15 squares), y: 0.5 m^2^ s^−2^ per big square (11.8 squares)","marks":2},{"text":"all six points correct (2, −1 per error); straight ruled line through (close to) the origin","marks":1},{"text":"title","marks":1}],"conf":"low","label":"(c)"},{"id":"week14.past.q2.d","kind":"self","q":"Determine the gradient of your graph, showing the triangle used.","marks":3,"level":2,"lines":3,"scheme":"Large triangle (at least half the line) shown (1); gradient ≈ ⟪5.90\\div 0.300\\approx 19.6⟫ (accept 19.0–20.2) (1); unit m s^−2^ (1).","points":[{"text":"Large triangle (at least half the line) shown","marks":1},{"text":"gradient ≈ ⟪5.90\\div 0.300\\approx 19.6⟫ (accept 19.0–20.2)","marks":1},{"text":"unit m s^−2^","marks":1}],"label":"(d)"},{"id":"week14.past.q2.e","kind":"self","q":"The loss of potential energy equals the gain in kinetic energy: ⟪mgh=\\tfrac{1}{2}mv^{2}⟫. Show that ⟪v^{2}=2gh⟫ and use your gradient to find g.","marks":4,"level":3,"lines":4,"scheme":"⟪mgh=\\tfrac{1}{2}mv^{2}⟫ → cancel m and multiply by 2: ⟪v^{2}=2gh⟫ (1); so gradient ⟪=2\\mathrm{g}⟫ (1); ⟪g=19.6\\div 2⟫ (1) ⟪=9.8\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (accept 9.5–10.1 from their gradient) (1).","points":[{"text":"⟪mgh=\\tfrac{1}{2}mv^{2}⟫ → cancel m and multiply by 2: ⟪v^{2}=2gh⟫","marks":1},{"text":"so gradient ⟪=2\\mathrm{g}⟫","marks":1},{"text":"⟪g=19.6\\div 2⟫","marks":1},{"text":"⟪=9.8\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫ (accept 9.5–10.1 from their gradient)","marks":1}],"label":"(e)"},{"id":"week14.past.q2.f","kind":"self","q":"What does the graph show about the relationship between v^2^ and h?","marks":2,"level":2,"lines":2,"scheme":"Straight line through the origin (1), so v^2^ is directly proportional to h (1).","points":[{"text":"Straight line through the origin","marks":1},{"text":"so v^2^ is directly proportional to h","marks":1}],"label":"(f)"},{"id":"week14.past.q2.g","kind":"self","q":"Suggest why the value of g found is slightly less than 10 m s^−2^, and give ONE precaution to improve the experiment.","marks":2,"level":2,"lines":3,"scheme":"Some energy is lost to friction/air resistance (or to the glider's PE not all becoming KE), so v is slightly smaller (1). Precaution: check the air track is clean and the air flow even / measure h with a metre rule at eye level / repeat each height and average (1).","points":[{"text":"Some energy is lost to friction/air resistance (or to the glider's PE not all becoming KE), so v is slightly smaller","marks":1},{"text":"Precaution: check the air track is clean and the air flow even / measure h with a metre rule at eye level / repeat each height and average","marks":1}],"label":"(g)"},{"id":"week14.past.q2.h","kind":"self","q":"Use your graph to find the height from which the glider must be released to reach 1.80 m s^−1^. Show your working on the graph.","marks":2,"level":2,"lines":3,"scheme":"⟪v^{2}=1.80^{2}=3.24\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫ (1); from graph ⟪h\\approx 0.165\\,\\mathrm{m}⟫ (accept 0.160–0.170 m) (1).","points":[{"text":"⟪v^{2}=1.80^{2}=3.24\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫","marks":1},{"text":"from graph ⟪h\\approx 0.165\\,\\mathrm{m}⟫ (accept 0.160–0.170 m)","marks":1}],"num":{"value":0.165,"sf":3,"unit":"m","unitTex":"\\mathrm{m}","min":0.16,"max":0.17},"label":"(h)","autoKind":"num"}]}],"n":108}]};
